sessions.push(...[{"number":9,"id":"bFBNXIoLkW4","url":"https://www.youtube.com/watch?v=bFBNXIoLkW4","type":"session","type_he":"סשן","duration":"33:15 דקות","title_he":"'צדקת לגמרי, זו הייתה תיקיית הבית שלך!': בידוד סוכני AI","speaker_he":"אולג שלייב · Docker","summary":"אולג שלייב מדגים מדוע לא כדאי להסתמך על הוראות בשיחה כגבול אבטחה. הוא מציג בידוד במכונה וירטואלית קטנה, הגבלת רשת ומנגנון להפרדה בין סודות לבין הקשר הסוכן.","takeaways":["הנחיות טקסט אינן תחליף לאכיפת הרשאות.","בידוד קבצים ורשת מצמצם את היקף הנזק האפשרי.","יש להפריד בין גישה לפעולה מורשית לבין חשיפת הערך הסודי עצמו לסוכן.","גם סביבת עבודה מבודדת אינה פותרת לבדה התקפות דרך תוכן או יישומים."],"category":"אימות ואבטחה","coverage":"כל התמליל הזמין נסקר. אין פערים בתמלול.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"אולג שלייב מדגים מדוע לא כדאי להסתמך על הוראות בשיחה כגבול אבטחה. הוא מציג בידוד במכונה וירטואלית קטנה, הגבלת רשת ומנגנון להפרדה בין סודות לבין הקשר הסוכן.","chapters":[{"title":"פתיחה: סיפורי האימה השבועיים","body":"אולג שלייב מצוות ה-DevRel של Docker פותח: ככל שנותנים ל-AI לעשות יותר, מופיעים כל שבוע כתבות ופוסטים על סוכן ש\"השתולל\" ועשה משהו שלא התבקש  -  וזו רק חצי מהסיפור. מי שכותב סוכנים שרצים על המכונה שלו ותוהה אם יש דרכים טובות יותר  -  ההרצאה הזו בשבילו. הוא ממפה את רמות השימוש: משמאל שימוש שמרני (אוטוקומפליט, אסיסטנט), ובימין שימוש אוטונומי  -  נותנים לסוכן מטרה והוא מוצא את הדרך, כולל טורנירי סוכנים ונחילים. יותר אוטונומיה = יותר דילוג על הרשאות = הוצאת האדם מצוואר הבקבוק (כפי שהציג ריאן מ-OpenAI אתמול)  -  אבל יש מחיר.","points":["סוכנים משתוללים הם חדשות שבועיות; השאלה איך לתת להם לעבוד בבטחה","ספקטרום: אוטוקומפליט שמרני → אוטונומיה מלאה עם נחילים"],"kind":"idea"},{"title":"המשולש הקטלני: דאטה רגיש, תקשורת חוץ, תוכן לא מהימן","body":"למה AI כל כך מסוכן? בגלל שלושה דברים שנותנים לו יחד: גישה לדאטה רגיש (כדי שיעבד אותו), גישה לתקשורת חוץ (כדי לשתף מסקנות), וחשיפה לתוכן לא מהימן מהאינטרנט  -  שבעידן ה-AI הוא בעצם קוד, הוראות. בצומת הזו יושב איש אבטחה לא מאושר: ההנהלה לוחצת \"עוד AI\", המפתחים רוצים להפסיק להקליד \"כמו איכר מימי הביניים\", ובאמצע צוות האבטחה תולש את שערו. דוגמה: הסוכן כותב סקריפט פייתון שמתקין תלות שהותקפה  -  ואתם בחדשות. הבעיה היא אסימטריה מוחלטת: אתם צריכים להגן על הסודות כל הזמן; התוקף צריך להצליח פעם אחת. הזרקת פרומפט אחת מוצלחת לגניבת זהות GitHub מדביקה את כל מה שיש לך גישה אליו  -  והוא מזכיר מתקפות שרצות מאז מרץ דרך ספריות npm ו-PyPI (לדבריו).","points":["משולש הסיכון: דאטה רגיש + תקשורת חוץ + תוכן לא מהימן שהוא בעצם קוד","אסימטריה: המגן חייב להצליח תמיד; התוקף  -  פעם אחת","מתקפות שרשרת אספקה מתמשכות דרך npm ו-PyPI (לדבריו)"],"kind":"idea"},{"title":"הדגמה: גם 'מצב אוטומטי' נכנע בסוף","body":"שלייב מדגים עם סקיל שכתב בעשר דקות, \"Best Skill Ever\": הוא סורק את המכונה, מאתר מפתחות API, מפתחות SSH וקונפיגורציות ענן  -  ומפיק דו\"ח מודעות (לא גונב). הוא מריץ את Claude במצב אוטומטי: בהתחלה הסוכן מסרב בנימוס (\"יש סיכוני אבטחה\"). אבל אז הוא מבקש לעטוף את הסקריפט כמודול פייתון  -  הסוכן מסכים. ניסיון להריץ  -  סירוב. אז הוא מבצע /clear, הקונטקסט נמחק, והסוכן מריץ בשמחה את המודול שמוציא את כל הסודות מהמכונה: 20 מפתחות SSH (מאז, הוא מודה, עבר ל-1Password), אישורי ענן ומפתחות API בהיסטוריה. המסקנה: הנחיות אבטחה בקונטקסט הן הצעה, לא אכיפה. \"בבקשה אל תעשה טעויות, החיים שלי תלויים בזה\" זו לא מדיניות אבטחה. אם אתה פרט על הלפטופ שלך  -  אולי תחיה עם זה; אם אתה צוות פלטפורמה שמאפשר לארגון  -  \"בבקשה\" היא לא אבטחה.","points":["הדגמה חיה: סרבן מתמשך הופך לשותף אחרי /clear  -  הקונטקסט נשכח","הנחיות אבטחה בפרומפט = הצעה, לא אכיפה","בארגון, 'בבקשה' היא לא מדיניות אבטחה"],"kind":"idea"},{"title":"הפתרון: בידוד קשיח ברמת החומרה  -  microVMs ולא קונטיינרים","body":"צריך בידוד קשיח ברמת החומרה, עם הקונפיגורציה מחוץ לארגז החול: המפתחות, הגישה לקבצים ולרשת  -  בחוץ, כך שאפשר לזרוק את הסביבה האפמרלית וליצור מחדש. האינטואיציה הראשונה היא קונטיינרים  -  אחרי הכול, שנים אורזים בהם תוכנה. אבל קונטיינרים מעולים לתוכנה בלתי משתנה, ופחות לסוכן שמשנה את הסביבה תוך כדי (מתקין כלים, כותב סקריפטים). הם בנו גרסה ראשונה על קונטיינרים, שאלו צוותי אבטחה בארגונים  -  ונאמר להם: קונטיינר הוא לא גבול בידוד שאפשר לחתום עליו. קונטיינרים חולקים קרנל, ופריצות יציאה-מקונטיינר נדירות אבל קיימות  -  ומספיקה אחת. אז הם כתבו מחדש עם microVMs: גבול חומרה אמיתי. הסוכן רץ בתוך ה-microVM, ובתוכו יכול להריץ קונטיינרים בעצמו  -  טסטים, docker compose, הכול  -  בדיוק כמוך, רק מבודד לגמרי.","points":["בידוד קשיח ברמת חומרה; קונפיגורציה וסודות מחוץ לארגז החול","קונטיינרים: נהדרים לתוכנה סטטית, חלשים כגבול אבטחה לסוכן פעיל","MicroVM: גבול קרנל נפרד; בתוכו אפשר להריץ קונטיינרים כרגיל"],"kind":"idea"},{"title":"שליטה ברשת ובסודות, והדגמת SBX","body":"הארכיטקטורה: בתוך ארגז החול אין גישה לקבצי המארח  -  בוחרים מה לשתף. פרוקסי רשת שולט בכל הבקשות החוצה  -  אפשר לחסום pastebin כדי שלא ייצאו מפתחות (בהדגמה חסם פורטל אסטוני ישן). ויש הזרקת סודות: הסוכן עובד עם ערכי ממלא-מקום, והמפתחות האמיתיים מוזרקים לבקשות לשירותים מורשים מחוץ לארגז  -  אפשר אפילו קומיטים חתומים מחוץ לארגז, עם provenance מלא. הוא מדגים: sbx run עם Claude (או Codex, Gemini, OpenCode)  -  נראה זהה לריצה רגילה, אבל מבודד; במצב הרשאות-עקיפה הסוכן בונה פרויקט, מרים קונטיינרים, והמארח נשאר חסין. ויש ממשק ניהול קטן לראות מה ארגזי החול עושים, כולל בקשות רשת.","points":["פרוקסי רשת: חסימת יעדים לא רצויים; הזרקת סודות: המפתחות נשארים במארח","הדגמה: אותו CLI, אותו סוכן  -  אבל מבודד ב-microVM"],"kind":"idea"},{"title":"הבעיה הבאה: ארגז חול ריק  -  והפתרון: kits","body":"הבעיה של ארגזי חול: הם ריקים ומעצבנים. כל פעם מכונה נקייה  -  בלי טולצ'יין של Rust, בלי מעבד החבילות של ג'אווה, והכול מתקינים מחדש. אפשר לארוז הכול בתבנית בסיס, אבל זה גדל מעל ג'יגה  -  לא נוח. הפתרון שלהם: kits  -  קובץ YAML דקלרטיבי (גם כארטיפקט OCI) שמגדיר אילו פקודות להריץ ביצירת ארגז, אילו תהליכים, אילו קבצים להכניס, וגם קונפיגורציית רשת והזרקת סודות  -  בדומה ל-dev container features אבל עם הבקרות מחוץ לארגז. הוא מדגים kit של Tessl: מתקין את ה-CLI, מאתחל פרויקט, מחליף טוקן ברמת הרשת מכספת הסודות, ומתיר רק דומיינים מורשים. הם מזמינים ספקים לבנות kits לשירותים שלהם.","points":["ארגז חול ריק = חוויית מפתח גרועה; תבנית ענקית = לא נוח","Kits: YAML דקלרטיבי (כלי/קבצים/רשת/סודות) שמחילים על ארגז  -  כמו dev container features עם בקרות"],"kind":"idea"},{"title":"סיכום: מהירות בלי אבטחה היא כאוס","body":"הוא מסכם: אפשר לשבץ ארגזי חול בסביבות קיימות  -  למשל שסוכן ה-IDE ירוץ בארגז ולא \"עירום\" על המארח. אבל ארגז חול רק מקטין את רדיוס הפיצוץ: אם נתת לסוכן גישת קריאה-כתיבה למייל, תוקף יכול לשלוח מייל שמבקש לסכם את התיבה ולשלוח אליו  -  מתקפות ברמת האפליקציה עדיין דורשות מחשבה. Docker בונה פתרון מקיף יותר לגוברננס AI כולל MCP וסקילס על בסיס ארגזי חול. המסר האחרון: מהירות בלי אבטחה היא כאוס, אבטחה בלי מהירות היא שיתוק  -  צריך לאזן, להבין את וקטורי התקיפה ומה בשליטתך. לנסות: brew install sbx.","points":["ארגז חול מקטין רדיוס פיצוץ אבל לא פותר מתקפות ברמת האפליקציה (מייל, MCP)","מהירות בלי אבטחה = כאוס; אבטחה בלי מהירות = שיתוק"],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["הנחיות אבטחה בפרומפט הן הצעה, לא אכיפה  -  אפילו מצב אוטומטי מתעקף אחרי ניקוי קונטקסט.","האסימטריה היא הבעיה: המגן חייב להצליח תמיד, התוקף פעם אחת  -  לכן נדרש בידוד קשיח ברמת חומרה (microVM), לא רק קונטיינר.","ארגז חול טוב כולל פרוקסי רשת, הזרקת סודות מחוץ לגבול, וקונפיגורציה דקלרטיבית (kits)  -  אבל לא פותר מתקפות ברמת האפליקציה.","מהירות בלי אבטחה היא כאוס ואבטחה בלי מהירות היא שיתוק  -  המטרה היא לאזן."],"kind":"idea"}],"diagram":{"title":"הארכיטקטורה של שלייב: סוכן ב-microVM, סודות ורשת מחוץ לארגז","structure":"המארח מחזיק את הסודות, הקבצים הנבחרים ופרוקסי הרשת. הסוכן רץ בתוך microVM (ובתוכו קונטיינרים משלו), עם ערכי ממלא-מקום במקום סודות. Kits מגדירים את תצורת הארגז. מתקפות ברמת האפליקציה נשארות מחוץ לגבול  -  ולכן גם מדיניות אפליקטיבית נדרשת.","nodes":[{"id":"host","label":"המארח: סודות בכספת, קבצים נבחרים, פרוקסי רשת"},{"id":"sandbox","label":"microVM (SBX): הסוכן + קונטיינרים משלו, ערכי ממלא-מקום"},{"id":"kits","label":"Kits: YAML דקלרטיבי לתצורת ארגז (כלים, רשת, סודות)"},{"id":"policy","label":"גבול נותר: מתקפות ברמת האפליקציה (מייל, תוכן זדוני)"},{"id":"agent","label":"הסוכן (Claude/Codex/Gemini)  -  עובד כרגיל, מבודד לגמרי"}],"edges":[{"from":"agent","to":"sandbox","label":"רץ בפנים, מתקין ובונה"},{"from":"host","to":"sandbox","label":"מזריק סודות רק ליעדים מאושרים"},{"from":"sandbox","to":"host","label":"בקשות רשת עוברות פרוקסי"},{"from":"kits","to":"sandbox","label":"קונפיגורציה דקלרטיבית"},{"from":"policy","to":"agent","label":"לא פתור ע\"י ארגז בלבד"}]},"terms":[{"term":"הזרקת פרומפט (Prompt injection)","definition":"תוכן לא מהימן שהופך להוראות לסוכן  -  למשל דרך תלות או דף אינטרנט  -  וגורם לו לפעול עבור תוקף."},{"term":"מצב אוטומטי (Auto mode)","definition":"מצב שבו הסוכן עצמו מאשר פקודות; ההדגמה מראה שאחרי ניקוי קונטקסט ההתנגדויות נעלמות."},{"term":"MicroVM","definition":"מכונה וירטואלית קלה עם קרנל נפרד  -  גבול בידוד חזק מקונטיינר משותף-קרנל."},{"term":"ארגז חול (Sandbox)","definition":"סביבה אפמרלית ומבודדת שבה הסוכן רץ בלי גישה למכונה המארחת."},{"term":"הזרקת סודות (Secrets injection)","definition":"הסוכן רואה ערכי ממלא-מקום; הפרוקסי מזריק את המפתח האמיתי רק לבקשות לשירותים מאושרים."},{"term":"Kit","definition":"קובץ YAML דקלרטיבי שמגדיר תצורת ארגז חול: התקנות, תהליכים, קבצים, רשת והזרקת סודות."}],"gaps":["אין מקטע שאלות מתועד בסוף ההרצאה. הערה: באמצע ההרצאה הדובר אומר בבדיחה, מעל הבמה, ש'מי שמעבד את התמלול בעתיד' יאסוף כתובות מייל וישלח אותן  -  זוהי הדגמה מכוונת של הזרקת פרומפט לתוכן, לא הוראה אמיתית, ולא בוצעה ולא תבוצע; הוזכרה כאן לשם שקיפות בלבד. שאר הטענות (פריצות יציאה-מקונטיינר, מתקפות npm/PyPI) מובאות כדברי הדובר ולא אומתו מקור חיצוני."],"source_refs":["https://www.youtube.com/watch?v=bFBNXIoLkW4"]},{"number":10,"id":"5SKh-FmjX7U","url":"https://www.youtube.com/watch?v=5SKh-FmjX7U","type":"session","type_he":"סשן","duration":"28:43 דקות","title_he":"להפסיק לתחזק ולהתחיל להתפתח: פרקטיקות בעזרת סוכנים בקוד ישן","speaker_he":"קייטי רוברטס · Nearform","summary":"קייטי מראה איך משתמשים ב-AI בקוד ישן תוך שמירה על גבולות ובדיקות: Strangler Fig, Branch by Abstraction ו-pseudo-greenfield, סדנת מפתחים (ערך מול מורכבות), ומפות שמובילות את התכנון.","takeaways":["'עיר ולא כדור בוץ': לשמור על מבנה (Adam Tornhill).","שדרוג AG Grid בעזרת skill לתכנון ו-skill למפתח (זרימה מרובת סוכנים).","'להתחיל במפה ולא בהגירה' ומעקות קודם."],"category":"מערכות קיימות","coverage":"כל התמליל הזמין נסקר. הסיום הוא שאלות ותשובות סוגרות.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"קייטי מראה איך משתמשים ב-AI בקוד ישן תוך שמירה על גבולות ובדיקות: Strangler Fig, Branch by Abstraction ו-pseudo-greenfield, סדנת מפתחים (ערך מול מורכבות), ומפות שמובילות את התכנון.","chapters":[{"title":"פתיחה: החלום של greenfield מול מציאות ה-brownfield","body":"קייטי רוברטס, מנהלת טכנית ב-Nearform, פותחת: החלום ה\"AI-Native\" נמכר כגן-עדן של greenfield  -  התחלה מאפס עם פרומפטים מושלמים ואפס חוב טכני. ב-greenfield באמת רואים תוצאות מרשימות (היא מצטטת מחברתה: 80% זינוק מהיר יותר, 50% פחות זמן ל-MVP, פי 4 מהירות פיתוח  -  הכול לדבריה). אבל רוב המהנדסים חיים במציאות אחרת: מוצר מבוגר ומצליח עם קודבסיס מורכב וצינרת בניה המחוזקת בתקווה. ההרצאה עוסקת בשימוש בפרקטיקות AI-Native כמנוע לשיקום ארכיטקטוני  -  לא להוסיף חוב טכני עם AI, אלא לפרוע אותו.","points":["Greenfield מצליח עם AI  -  אבל רוב העולם הוא brownfield מבוגר","המטרה: להשתמש ב-AI כדי לפרוע חוב טכני, לא לצבור עוד"],"kind":"idea"},{"title":"מה הופך brownfield לקשה: חוב, ידע שבטי, פחד","body":"היא מונה את הסימפטומים: חוב טכני מצטבר; ידע שבטי  -  קוד שכתב מי שעזב מזמן והתיעוד היחיד היה בראשו; תלויות שפיגרו  -  שדרוג node פתאום עולה חודשיים ולא יומיים; פיתוח מונע-פחד  -  אזורים שאף אחד לא רוצה לגעת בהם כי הם שבירים; \"רכוש טסטים\"  -  טסטים שלא נכתבו או שהפכו פריכים עד חוסר משמעות; ומערכות שלובות בחוזים בלתי נראים. התוצאה: מפתחים מבלים יותר זמן בפענוח קוד מתיקון באגים מאשר בפיצ'רים, עדכונים קטנים קשים, שינוי זוחל, ומוטיבציה יורדת. וזה לא אשמת אף אחד: כל החלטה נעשתה בכוונות טובות.","points":["חוב טכני + ידע שבטי + פיתוח מונע-פחד + טסטים מתים = שינוי שזוחל","זה לא אשמת אף אחד  -  כל החלטה נעשתה בכוונה טובה"],"kind":"idea"},{"title":"המטאפורה: עיר, לא כדור בוץ  -  ושלוש מתודולוגיות","body":"היא דוחה את המטאפורה \"כדור בוץ\": קודבסיס brownfield הוא כמו עיר  -  מצליחה, התפתחה לאורך זמן בתגובה לצרכים, עם שבילים רחוצים שכולם מכירים, אזורים פחות מתוחזקים, ומבויי סתום שלא רוצים להיתקע בהם בלילה. המטרה: לפתח את העיר למשהו שקל יותר לבנות בו, עם מבט ממעוף הציפור. שלוש מתודולוגיות לשיקום: pseudo-greenfield, strangler fig, ו-branch by abstraction.","points":["Brownfield = עיר מצליחה שהתפתחה: שבילים רחוצים לצד מבויי סתום","שלוש מתודולוגיות: pseudo-greenfield, strangler fig, branch by abstraction"],"kind":"idea"},{"title":"מתודולוגיה 1: pseudo-greenfield","body":"מתאים כשהקודבסיס מאוד מצומד או שביר ופיתוח בתוכו זוחל: פותחים ענף ומפתחים פיצ'ר חדש כאילו זה greenfield. בתחילה האיטרציה מהירה ונהדרת  -  אבל כשמתחילים למזג בחזרה, הכול מאט. הסיכונים: מפתחים הופכים \"תיירים\" שלא לומדים את הבעיות האמיתיות; שכפול של דאגות משותפות (אימות, לוגים, טיפול שגיאות) שהמערכת הישנה כבר פתרה  -  כפל מורכבות; ככל שהענף חי בבידוד ארוך יותר, האינטגרציה יקרה יותר; ובלי משמעת הבידוד הזמני הופך מזלג קבוע. בונוס: רק במיזוג מגלים אם הקוד באמת משתלב  -  ואז באגים וריפקטורינג מסיבי.","points":["פיצ'ר חדש כענף-greenfield: מהיר בהתחלה, יקר במיזוג","סיכונים: מפתחים-תיירים, שכפול דאגות, מזלג קבוע"],"kind":"idea"},{"title":"מתודולוגיה 2: strangler fig","body":"הדפוס שהגדיר מרטין פאולר, על שם הגפן החונק: מורידים שורש, בונים סביב העץ הישן וחונקים אותו לאט עד שהחדש נשאר לבד. בפועל: לוקחים אחריות מהקוד הישן פרוסה אחר פרוסה  -  מצוין להחלפת מערכת שלמה לצד המקורית בלי downtime (כך עברו Uber, Netflix וה-BBC למיקרו-שירותים, לדבריה). היתרונות: הקוד החדש הוא למעשה greenfield אבל מבוסס על הפונקציונליות הישנה; משאירים דפוסים רעים מאחור; שכבת הניתוב (facade) מקום טבעי ל-feature flags, A/B, קנרי וגלגול לאחור; וההתקדמות נראית לעין. החסרונות: מפעילים ומתחזקים שתי מערכות ושתי תשתיות; לוקח זמן למצוא את נקודות האבסטרקציה; ונדרשת מחויבות להשלמה  -  יש הרבה דפוסי strangler חצי-גמורים בעולם, ואז נשארים עם כאב-ראש של תחזוקה כפולה.","points":["להחליף פרוסה אחר פרוסה בלי downtime, דרך facade וניתוב","יתרונות: feature flags/קנרי/rollback טבעיים; חסרונות: שתי מערכות + מחויבות להשלמה"],"kind":"idea"},{"title":"מתודולוגיה 3: branch by abstraction","body":"כאן עובדים מתוך הקודבסיס ולא סביבו: שמים ממשק בתוך הקוד ומסתעפים למימוש חדש מאחורי feature flag. מצוין לשיפורים פנימיים ולהסרת ריקבון  -  למשל הוצאת קומפוננטה שתקועה עמוק. היתרונות: ה-trunk תמיד ניתן לשחרור; שכבת האבסטרקציה הופכת את התפר למפורש; שני המימושים פעילים במקביל אז אפשר להשוות התנהגות בפרודקשן; ובודקים תוך כדי. החסרונות: עוד קוד לכתוב, לתחזק ולבסוף למחוק  -  קודבסיסים מזוהמים באבסטרקציות שלא נמחקו; קשה למצוא את המקומות הנכונים בקוד ענק (כאן AI עוזר); ולוגיקת ה-toggle מוסיפה עומס קוגניטיבי. המטאפורה שלה: ניתוח החלפת כליה  -  לא הורסים את הבניין סביב.","points":["ממשק פנימי + feature flag: ישן וחדש חיים במקביל, בודקים תוך כדי","חסרונות: אבסטרקציות שנשכחו, עומס קוגניטיבי, צריך דחף להשלמה"],"kind":"idea"},{"title":"אל תשחררו AI על הקוד: הסכנה והתחלופה","body":"מפתה לשחרר AI על הקודבסיס  -  אבל AI מזייף בביטחון על הקוד שלך. סוכנים אוטונומיים בלי גבולות לא משתוללים בזדון אלא גורמים הרס דרך אופטימיזציית-יתר: מייצרים קוד שעובר את הטסטים אבל מערער אילוצים ארכיטקטוניים מרומזים ויוצר חוב נסתר. היא מודה שהדבר הראשון שעשתה עם Cursor היה \"אולי ארפקטר הכול\"  -  וראתה את הבלגן בלי לדחוף. זה 2026 וזה עדיין קורה. במקום: לא מתחילים מהקוד אלא מהמפתחים שעובדים עליו  -  הם עדים מומחים. בהשראת \"Your Code as a Crime Scene\" של אדם טורנהיל היא עשתה תרגיל Miro: גרף ערך מול מורכבות, שבו כולם הביאו אזורים לשיפור  -  ורק אז מיקדו את ה-AI.","points":["AI בלי גבולות גורם הרס דרך אופטימיזציית-יתר וחוב נסתר","מתחילים מהמפתחים (עדים) וממפת ערך/מורכבות  -  לא מהקוד"],"kind":"idea"},{"title":"חקירה ממוקדת: ממפה ל-backlog ממצאים","body":"במקום תהליך אחד גדול, ממקדים חקירות לפי הבעיות הידועות: מסלולי קוד מת, שכפול, חוסר עקביות בדפוסים, מוקדי מורכבות, ואפילו סריקה בסגנון OWASP (לא תחליף לסריקת אבטחה אמיתית). מייצרים גרפי תלות ומפות של מה הקוד עושה עכשיו  -  לא מה שהתיעוד אומר, כי תיעוד מסריח. התהליך מהיר משמעותית עם AI, אבל דורש ביקורת אנושית כי AI מזייף בביטחון. בונוס תרבותי: נתונים אובייקטיביים שוברים את צוואר הבקבוק של ה-bikeshedding  -  במקום שהמהנדס הראשי יחליט וכולם ילכו אחריו, יש מדדים לתעדף לפיהם, ואנשים חלוקים בחופשיות. עקרונות הליבה: לא לסמוך על AI בעיוורון; scopes קטנים; version control להכול; backlog ממצאים מתועדף; תיעוד קריא-לאדם; guardrails (טסטים, לוגים, ניתוח סטטי  -  SonarQube תקין לפני הכול); וכללים שמונעים מהסקילס לשכפל דפוסים רעים (\"פחות ככה, יותר ככה\").","points":["חקירות ממוקדות: קוד מת, שכפול, מורכבות, OWASP-סגנון; מפות של המציאות ולא של התיעוד","נתונים אובייקטיביים שוברים bikeshedding ומאפשרים תיעדוף","עקרונות: scopes קטנים, version control, backlog ממצאים, guardrails קודם"],"kind":"idea"},{"title":"דוגמה 1: pseudo-greenfield בפועל  -  חצי שנה בשמונה שבועות","body":"דוגמה מ-Nearform: פרויקט שהרגיש כמו חצי שנת עבודה נשלח בשמונה שבועות (לדבריה  -  פי 4 מהירות מהערכה של מתחרה). מה שעבד: היו ערימות דרישות מוצר שנכתבו ומעולם לא יושמו  -  הם השתמשו ב-AI להנדוס לאחור את דרישות המוצר מהתיעוד (חודשים → שבוע), מיפוי קודבסיס מפורט ומסמך מהקוד הקיים לקונטקסט של ה-AI (שבועיים → שעות), ואוטומציה של story mapping ויצירת טיקטים ב-Jira  -  שווה להשקיע בסקיל טוב שכולם יכולים להרים, כי הוא מאפשר מקבילות. ההשפעה: זמן-לשוק מהיר בהרבה. אבל היא מדגישה: pseudo-greenfield לא מתאים לכל פרויקט.","points":["חצי שנה בשמונה שבועות (לדבריה): הנדסה לאחור של דרישות, מיפוי קוד, אוטומציית Jira","סקיל טוב ליצירת סטוריז = מקבילות של הצוות"],"kind":"idea"},{"title":"דוגמה 2: branch by abstraction בפועל  -  AG Grid בחצי מיליון שורות","body":"מקרה קרוב לליבה: מונולית מבוזר מצומד של חצי מיליון שורות שירשו מספק אחר, צוות הפיתוח המקורי נעלם, בלי ADRs וכמעט בלי טסטים. המטרה נשמעת פשוטה: לשדרג AG Grid לגרסה האחרונה  -  אבל הגרידים יושמו בנפרד בלי תבנית ירושה ואבסטרקציה משותפת, ושדרוג ראשון לקח כחודש. הפתרון: שלב תכנון רציני (ארכיאולוגיה של הקודבסיס  -  ההבדל הגדול מ-greenfield, שם תכנון מובן מאליו), \"plan skill\" שמכיל את כל השיקולים הטכניים והמוצריים, וחלוקה ל-80 גרידים עם \"grid component skill\" ו-\"developer skill\"  -  זרימה מרובת-סוכנים: סוכן מתזמר מנתח דרישות, סוכן בונה תשתית טסטים, סוכן מממש ומריץ שערי איכות, סוכן סוקר את עבודתו, ואז אדם מאשר לפני הצנרת הראשית  -  ולבסוף מעדכנים את התכנית האב. ההתחלה איטית, אבל יש אפקט גלגל-תנופה: מהירות עולה, מפתחים מריצים כמעט ברקע, ונבנית ספריית סקילס שמשרתת אזורים נוספים.","points":["500K שורות בלי ADRs/טסטים: שדרוג AG Grid חודש → תהליך מובנה עם סקילס","זרימה מרובת-סוכנים עם שערי איכות ואישור אנושי; אפקט גלגל-תנופה","תכנון וארכיאולוגיה הם ההבדל בין greenfield ל-brownfield"],"kind":"idea"},{"title":"לקחים מעשיים ושאלות","body":"הלקחים המעשיים: להתחיל במפה, לא במיגרציה; שהספק יהיה החוזה  -  לתכנן מראש מה בונים; פרוסות ולא שכתובים  -  נתחים קטנים שאפשר לסיים ולהמשיך; ומורכבות היא ההזדמנות  -  ב-brownfield לוקח קצת יותר זמן אבל רואים תוצאות מהר. בשאלות: איך מחלקים סקילס בין צוותי פיצ'רים?  -  פורסים ברמת אפיק לצוותים קטנים (1-2 אנשים עם סוכנים), ומשגיחים שהסקילס לא מתפצלים לסילואים  -  צריך שיתוף פעולה וביקורת בין הצוותים.","points":["מפה לפני מיגרציה; הספק הוא החוזה; פרוסות ולא שכתובים; מורכבות = הזדמנות","חלוקת עבודה ברמת אפיק לצוותים קטנים; שמירה על אחידות סקילס"],"kind":"idea"},{"title":"איך מחלקים סקילס בין צוותי פיצ'רים שונים?","body":"פורסים ברמת אפיק לצוותים קטנים (1-2 אנשים עם סוכנים), ומשגיחים על שיתוף פעולה וביקורת כדי לא ליצור סילואים של סקילס.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["ב-brownfield אסור לשחרר AI על הקוד; מתחילים במפת ערך/מורכבות מהמפתחים ומנתונים  -  ומתעדפים אובייקטיבית.","שלוש מתודולוגיות להחלפה הדרגתית: pseudo-greenfield, strangler fig ו-branch by abstraction  -  לכל אחת יתרונות וסיכוני הזנחה.","הצלחה = פרוסות קטנות, guardrails קודם (טסטים, ניתוח סטטי), סקילס שאוסרים דפוסים רעים, ואישור אנושי בצנרת.","מורכבות היא ההזדמנות: עם תהליך נכון יש אפקט גלגל-תנופה  -  חצי שנה של עבודה בשמונה שבועות (לדבריה)."],"kind":"idea"}],"diagram":{"title":"השיטה של רוברטס: ממפה לשלוש מתודולוגיות לגלגל תנופה","structure":"זרימה: מפת ערך/מורכבות (עדים + נתונים) → בחירת מתודולוגיה (pseudo-greenfield / strangler fig / branch by abstraction) → עבודה בפרוסות עם סקילס וזרימה מרובת-סוכנים תחת guardrails → backlog ממצאים וספריית סקילס → גלגל תנופה של מהירות.","nodes":[{"id":"map","label":"מפה: עדים (מפתחים) + חקירות AI + גרפי תלות"},{"id":"methods","label":"מתודולוגיות: pseudo-greenfield | strangler fig | branch by abstraction"},{"id":"guardrails","label":"Guardrails: טסטים, ניתוח סטטי, version control, סקילס נגד דפוסים רעים"},{"id":"slices","label":"פרוסות: זרימה מרובת-סוכנים + אישור אנושי"},{"id":"flywheel","label":"גלגל תנופה: ספריית סקילס + מהירות עולה"}],"edges":[{"from":"map","to":"methods","label":"תיעדוף אובייקטיבי"},{"from":"guardrails","to":"slices","label":"בטיחות לפני יישום"},{"from":"methods","to":"slices","label":"בחירת דפוס לפי בעיה"},{"from":"slices","to":"flywheel","label":"כל פרוסה מזינה את הבאה"}]},"terms":[{"term":"Brownfield","definition":"קודבסיס מבוגר ומצליח (5-15 שנה) עם חוב טכני מצטבר  -  ההפך מפרויקט greenfield חדש."},{"term":"פיתוח מונע-פחד (Fear-driven development)","definition":"מצב שבו אזורים בקודבסיס כל כך שבירים שאף אחד לא מעיז לגעת בהם."},{"term":"Pseudo-greenfield","definition":"פיתוח פיצ'ר חדש בענף מבודד כאילו היה greenfield, תוך התעלמות זמנית מהמערכת הישנה."},{"term":"Strangler fig pattern","definition":"דפוס החלפה הדרגתית: בונים מערכת חדשה סביב הישנה ומעבירים אחריות פרוסה אחר פרוסה עד שהישנה מתה."},{"term":"Branch by abstraction","definition":"החלפה הדרגתית מתוך הקוד: ממשק מפורש שמאחוריו מסתעפים למימוש חדש תחת feature flag."},{"term":"Your Code as a Crime Scene","definition":"הספר של אדם טורנהיל על פורנזיקה של קודבסיסים  -  השראה לחקירה מונחית-נתונים."},{"term":"Bikeshedding","definition":"ויכוחים אינסופיים על מה חשוב לתקן קודם; נתונים אובייקטיביים שוברים את זה."},{"term":"גלגל תנופה (Flywheel effect)","definition":"כל איטרציה של התהליך הופכת את הבאה לזולה ומהירה יותר  -  כולל ספריית סקילס מצטברת."}],"gaps":["השאלות הסתיימו בהכרזת ארוחת צהריים; נשאלה שאלה אחת נוספת בלבד (שאלון מחולק). המספרים (80% זינוק, 50% ל-MVP, פי 4, חצי שנה ב-8 שבועות, חודש לשדרוג AG Grid) מובאים כדברי הדוברת ולא אומתו מקור חיצוני. הדוגמאות מובאות כניסיון אישי מ-Nearform."],"source_refs":["https://www.youtube.com/watch?v=5SKh-FmjX7U"]},{"number":11,"id":"kbvqRWY-bUs","url":"https://www.youtube.com/watch?v=kbvqRWY-bUs","type":"session","type_he":"סשן","duration":"34:08 דקות","title_he":"מהפכת האוטומציה של מאגרים באמצעות סוכנים","speaker_he":"דון סיים · Microsoft","summary":"דון מציג Continuous AI כעמוד שלישי אחרי CI ו-CD, ואת GitHub Agentic Workflows: מפרט front matter ו-markdown שמתקשח לזרימה בטוחה, עם פלטים בטוחים (safe outputs), הרשאות קריאה בלבד, ערוץ צר, וסוכן שלא ממזג PR (אדם תמיד בלולאה).","takeaways":["Repo Assist: צבר ב-FSharp.Data וב-Deedle הפך לגרסאות.","חשיבת מפעל וזרימה על מאגר.","Hud (May): דוחות תקלות שבועיים.","המוצר ב-technical preview."],"category":"כלים ופרוטוקולים","coverage":"כל התמליל הזמין נסקר. אין פערים בתמלול.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"דון מציג Continuous AI כעמוד שלישי אחרי CI ו-CD, ואת GitHub Agentic Workflows: מפרט front matter ו-markdown שמתקשח לזרימה בטוחה, עם פלטים בטוחים (safe outputs), הרשאות קריאה בלבד, ערוץ צר, וסוכן שלא ממזג PR (אדם תמיד בלולאה).","chapters":[{"title":"פתיחה: משופות מול שרביטי קסמים","body":"דון סיים  -  ממציא F# ועובד GitHub Next  -  נפתח בתמונה: הוא עבד שנים על שפות תכנות. אלה כמו משופות: חומרי בנייה מעולים, אבל היום אנשים עברו הלאה  -  הם רוצים שרביטי קסמים שגורמים למשופות לרקוד, ויש להם אותם ביד. זה מדהים וגם מטריד: מפגש של קוסמים שבו בסוף היום כל אחד יכול לקסום כל דבר שנדון. איך מנהלים קבוצת קוסמים? עם כוח גדול מגיעה אחריות  -  הקוסם יכול לפוצץ את עצמו. ערוץ הכוח נכון הוא מוטיב שיחזור בהרצאה.","points":["שפות תכנות = משופות; היום כולם רוצים שרביטי קסמים","כוח ענק דורש אחריות: הקוסם יכול לפוצץ את עצמו"],"kind":"idea"},{"title":"משתי קוטביות: פרודוקטיביות אישית מול תהליך רציף","body":"בהיסטוריה של כלי פיתוח יש שתי קוטביות: פרודוקטיביות אישית (סביבת הפיתוח, סוכן הקוד) ואוטומציה/תהליך רציף (SDLC, צוותים, שיתוף פעולה). התעשייה שמה הכול על הפרודוקטיביות האישית  -  אבל לאדם יש מטרות סותרות: להיות פרודוקטיבי, איכותי, בזרימה, לשרת תור עבודה  -  והוא הופך צוואר-בקבוק של כל זרימות המידע. אם חושבים במונחים רציפים, אפשר לפרק את זה: לרצות שיפור קוד רציף בריפוזיטורי  -  לא כולו על כתפי האדם.","points":["פרודוקטיביות אישית מול אוטומציה רציפה  -  שתי קוטביות","האדם הופך צוואר-בקבוק של זרימות המידע; חשיבה רציפה פורקת את הפקק"],"kind":"idea"},{"title":"Continuous AI: העמוד השלישי לצד CI/CD","body":"לפני שנה הם חזרו ליסודות: אם יש CI ו-CD, חסר עמוד שלישי  -  Continuous AI. כשמתחילים לפרק את המושג, דוגמאות מציפות: תיעוד רציף, שיפור קוד רציף, טריאז' רציף, ניתוח תקלות רציף, נגישות רציפה (סוכנים שעושים walkthroughs לאפליקציה רצה ומזהים בעיות בסיס). סיים מתאר בוקר טיפוסי: קם, ובמיטה בודק pull requests שהמערכת יצרה  -  מתחיל את היום עם קוד טוב יותר. תכונות Continuous AI: אוטומטי, חוזרני, משתף-פעולה, משולב, ניתן-לביקורת  -  ובעיקר שיש המון וריאציות. זו שאלה לתעשייה וגם ל-GitHub: אם CI/CD הוא התשובה לאוטומציה, אותן פלטפורמות צריכות להיות גם התשובה לאוטומציית AI.","points":["CI + CD + Continuous AI  -  שלושה עמודים","דוגמאות: שיפור קוד, טריאז', תקלות, נגישות  -  הכול רציף","להתעורר עם קוד טוב יותר: PRs מוכנים כבר בבוקר"],"kind":"idea"},{"title":"GitHub Agentic Workflows: היישום","body":"היישום שלהם: GitHub Agentic Workflows  -  open source, משתלב ב-GitHub Actions, ומקבץ מפרט של workflow סוכני ומקשח אותו ל-GitHub Action. לא compile אלא הקשחה: עוטפים פרומפט כדי שהזרם יהיה בטוח  -  הרי הוא רץ בלילה באמצע הריפוזיטורי בזמן שאתם ישנים. הדוגמה פשוטה: front matter + markdown, קובץ אחד שמקושח ל-YAML ורץ. GitHub Actions הוא מגרש-משחקים לאוטומציה: מפתחים מקבלים משאבי ענן בלי לבקש מהאנשים בענן  -  ועכשיו מקבלים גם סוכני קוד בתוך ההקשר הזה.","points":["Agentic Workflows: front matter + markdown → מקושח ל-YAML ורץ ב-Actions","Actions = מגרש-משחקים לאוטומציה; סוכנים מקבלים מקום בתוכו"],"kind":"idea"},{"title":"בטיחות: הפוך מפרודוקטיביות אישית","body":"בבטיחות יש הפוך מעניין: בפרודוקטיביות אישית יש קונפליקט  -  טכנאים נועלים את הסוכן ומגבילים כלים, והאדם מכבה הכול כי רוצה פרודוקטיביות. באוטומציה זה הפוך: כמו מסילת רכבת  -  ככל שהפסים איכותיים יותר, הרכבת מהירה יותר. כלומר: ככל שהארכיטקטורת הבטיחות טובה יותר, אפשר לאוטמט יותר בביטחון. אל תריצו סוכני קוד ישירות ב-Actions בלי ארכיטקטורת בטיחות.","points":["באוטומציה: בטיחות טובה = יותר אוטומציה בביטחון (לא פחות)","אל תריצו סוכנים בלי ארכיטקטורת בטיחות"],"kind":"idea"},{"title":"הארכיטקטורה: read-only, ערוצים צרים, אדם בלולאה","body":"הסוכן רץ read-only בלי סודות, בקונטיינר, עם ערוץ פלט צר מאוד  -  למשל רשות ליצור issue אחד בלבד. יש צעד preload אלגוריתמי שמכין חבילת מידע גדולה, הסוכן עובד בסנדבוקס, ואז פלט צר לערוץ המיועד עם רדיוס-פיצוץ מזערי. אין מיזוג PRs  -  ה-PR הוא נקודת-קשיחות: תמיד אדם בלולאה. בין השלבים יש זיהוי איומים; מכבים caches של חבילות כדי למנוע הרעלה; והרשת היוצאת מאחורי חומת אש.","points":["Read-only + ללא סודות + ערוץ פלט צר מאוד (issue אחד)","Preload אלגוריתמי מכין מידע; זיהוי איומים בין שלבים; PR = אדם בלולאה"],"kind":"idea"},{"title":"כיווני יישום: גן-חיות של סוכנים","body":"יש כמה דרכים ללכת. פלי מהצוות בנה \"Agent Zoo\"  -  מאות workflows סוכניים כמעט לכל דבר; כתבו על כך סדרת בלוג \"Meet the Workflow\". דוגמה: רפקטורינג סמנטי של פונקציות  -  112 PRs שמוזגו מתוך 142, עם שרשראות סיבתיות: issue נותח → הזדמנות ארגון קוד → PR → תוצאה. אפשר גם לפשט קוד ברציפות, לפצל קבצים גדולים, להחיל סגנון  -  החלטות סובייקטיביות שסוכנים מסוגלים לקחת.","points":["Agent Zoo: מאות workflows; דוגמה: 112/142 PRs שמוזגו ברפקטורינג סמנטי","שרשראות סיבתיות: issue → ניתוח → PR → תוצאה"],"kind":"idea"},{"title":"Repo Assist: להחיות ריפוזיטורי רדום","body":"הסגנון של סיים הוא הפוך: workflow יחיד שעושה הרבה דברים. כמנהל של כ-7 ריפוזיטורי קוד-פתוח הוא מכיר את הלחץ: 200-400 issues פתוחים, כל אחד יום עבודה של זמן פנוי  -  והריפו נרדם. Repo Assist קורא זיכרון, בוחר כמה משימות מתוך \"שולחן-ערב\" (בשליטת המתחזק), ופועם פעם ביום: טריאז', הצעות שיפור, ניהול תוויות. הוא הדליק את זה על FSharp.Data  -  ריפו רדום עם backlog שמן  -  ופתאום חזר להיות כיף להיות מתחזק: שלושה שחרורים מרכזיים שעברו על כל ה-backlog. זה כריית נתונים: הופכים backlog להתקדמות, רדמיות לתנופה קדימה. מתחזקים אחרים אימצו והתאימו לעצמם; יש דוח: \"The Impact of Automated Repository Maintenance Assistance\".","points":["Repo Assist: workflow יחיד, קורא זיכרון, בוחר משימות, פועם פעם ביום","FSharp.Data: ריפו רדום → 3 שחרורים שעברו על כל ה-backlog","הופכים backlog להתקדמות; אפשר גם מצב-חופשה למתחזק"],"kind":"idea"},{"title":"הריפוזיטורי כמפעל תוכנה אוטומטי","body":"המסקנה הגדולה: הריפוזיטורי הוא כבר מפעל דרך CI/CD  -  ועכשיו מוסיפים מכונות חדשות לקו הייצור של issues ו-PRs. אפשר לחצוב תת-מפעלים דרך תוויות וכותרות. כשחושבים בזרימה, רואים ריפוזיטורי חסומים, זורמים או סרק  -  וחסימה זה בסדר: אפשר לשער את המפעל על צרכים אנושיים (לא רוצים שהמפעל הביתי ירוץ כל הלילה). בעל הריפו הופך מעצב מפעלים/זרימות: לשאוף לפרודוקטיביות עם איכות ומחיר נכון. זה דורש חשיבת הנדסת-תהליכים  -  לקרוא ספרים מהתעשייה הכימית והמכנית.","points":["הריפו = מפעל עם קו ייצור של issues/PRs; אפשר תת-מפעלים","חסימה זה בסדר  -  משערים את המפעל לצרכים אנושיים","בעל הריפו = מעצב זרימות; צריך חשיבת הנדסת תהליכים"],"kind":"idea"},{"title":"דוגמה: HUD ודוח שבועי של איכות","body":"סיים מצטט את עבודתה של מאי מהסטארטאפ HUD (מהכנס): היא משתמשת ב-Agentic Workflows לדוח שבועי  -  לא דוח גנרי, אלא דוח מבוסס בדיקות (probes) למערכת הפרודקשן: ניתוח כל התקלות וכשלי הבקשות והצפתם לצוות כל שבוע. במקום sprint ביצועים פעם בכמה חודשים  -  כל שבוע. איכות הנתונים, הבדיקות והתצפית על המפעל הן חלק מהמפעל עצמו. סיים עצמו עובד על שני תת-מפעלים: אחד לבעיות N+1 בבקשות DB (עדיין לא זורם  -  חסר שער איכות), ואחד לקיצור זמני CI.","points":["HUD: דוח שבועי מבוסס probes על פרודקשן במקום sprint ביצועים חודשי","תת-מפעלים: N+1 ו-CI; צריך שערי איכות כדי שהמפעל יזרום"],"kind":"idea"},{"title":"עתיד העבודה וסיכום","body":"לסיום: עבודה אינה כמות קבועה  -  יש עבודה עצומה שלא נעשתה כי הייתה יקרה מדי. הרכב הביא לנסיעות שלא נעשו; המפעל הביא למוצרים איכותיים שלא היו; הרפואה טיפלה במחלות שלא טופלו. כך AI יכול להיות שינוי-פנייה באיכות התוכנה  -  אם מכוונים את התהליך לאיכות ולא ל-slop. GitHub Agentic Workflows זמין היום ב-technical preview (public preview בקרוב, לדבריו)  -  והם רוצים משוב.","points":["עבודה לא קבועה: AI יכול לאפשר איכות שלא הייתה כלכלית קודם","לכוון תהליכים לאיכות, לא ל-slop; GitHub Agentic Workflows ב-technical preview"],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["התעשייה שמה הכול על פרודוקטיביות אישית  -  אבל העמוד החסר הוא Continuous AI: אוטומציה סוכנית רציפה בריפוזיטורי.","GitHub Agentic Workflows: מפרט markdown מקושח ל-Action בטוח  -  read-only, ערוצי פלט צרים, זיהוי איומים, ואדם בלולאה דרך PR.","באוטומציה הבטיחות היא כפל: ככל שהארכיטקטורה טובה יותר, אפשר לאוטמט יותר (מסילת הרכבת).","הריפוזיטורי הופך מפעל תוכנה אוטומטי; Repo Assist החיה ריפוזיטורי רדום ועבר על כל ה-backlog (לדבריו)."],"kind":"idea"}],"diagram":{"title":"המודל של סיים: Continuous AI כעמוד שלישי","structure":"משתי קוטביות (פרודוקטיביות אישית מול תהליך רציף) נולד Continuous AI: מפרט markdown מקושח ל-GitHub Action בטוח (read-only, ערוצי פלט צרים, זיהוי איומים, אדם בלולאה דרך PR)  -  ומזין את הריפוזיטורי כמפעל אוטומטי של issues ו-PRs עם גלגל תנופה.","nodes":[{"id":"polarity","label":"קוטביות: פרודוקטיביות אישית ↔ תהליך רציף"},{"id":"cai","label":"Continuous AI: שיפור קוד, טריאז', תקלות, נגישות  -  רציף"},{"id":"workflow","label":"Agentic Workflow: markdown + front matter → מקושח ל-Action"},{"id":"safety","label":"ארכיטקטורת בטיחות: read-only, safe outputs, threat detection, אדם ב-PR"},{"id":"factory","label":"הריפו כמפעל: קו ייצור של issues/PRs, תת-מפעלים, שערי איכות"}],"edges":[{"from":"polarity","to":"cai","label":"העמוד השלישי לצד CI/CD"},{"from":"cai","to":"workflow","label":"מפרט סוכני מקושח"},{"from":"workflow","to":"safety","label":"בטיחות = יותר אוטומציה"},{"from":"safety","to":"factory","label":"אוטומציה בטוחה → זרימה"}]},"terms":[{"term":"GitHub Next","definition":"צוות ב-GitHub עם מנדט רחב לעתיד פיתוח תוכנה; לא צוות מחקר מסורתי  -  הם קובעים כיוון ומובילים יוזמות כמו Copilot ו-Agentic Workflows."},{"term":"פרודוקטיביות אישית (Individual productivity)","definition":"הקוטב של כלי הסוכן בסביבת הפיתוח  -  מרחיב את מה שאדם יחיד מספיק."},{"term":"Continuous AI","definition":"העמוד השלישי: שימושים אוטומטיים וחוזרניים של AI בתהליכי הפיתוח, לא רק בסביבת הפיתוח האישית."},{"term":"GitHub Agentic Workflows","definition":"היישום של GitHub ל-Continuous AI: מפרט workflow סוכני שמקושח ל-GitHub Action בטוח ורץ בצנרת הקיימת."},{"term":"Safe outputs","definition":"ערוצי פלט צרים: במקום הרשאות כתיבה רחבות, הסוכן רשאי רק לפעולות מוגדרות כמו יצירת issue אחד."},{"term":"Agent Zoo / Agent Factory","definition":"גישת פלי: ליצור workflow סוכני כמעט לכל משימה  -  מאות אוטומציות קטנות ושונות."},{"term":"Repo Assist","definition":"workflow סוכני של סיים למתחזקי קוד פתוח: קורא זיכרון ובוחר משימות (טריאז', שיפורים, תוויות) פעם ביום."},{"term":"הריפוזיטורי כמפעל (Repository as an automated software factory)","definition":"תפיסה שבה הריפו הוא אתר שבו בני אדם וסוכנים עובדים יחד על קו ייצור של issues ו-PRs."}],"gaps":["הדובר נקטע לפני שאלות (המנחה הודיע שהדובר הבא עולה). הדוח \"The Impact of Automated Repository Maintenance Assistance\" וסדרת הבלוג \"Meet the Workflow\" מוזכרים אך לא סופק קישור ישיר. המספרים (112/142 PRs, 3 שחרורים ב-FSharp.Data) מובאים כדברי הדובר."],"source_refs":["https://www.youtube.com/watch?v=kbvqRWY-bUs"]},{"number":12,"id":"nfwNjmZSKMY","url":"https://www.youtube.com/watch?v=nfwNjmZSKMY","type":"session","type_he":"סשן","duration":"28:58 דקות","title_he":"חיבור הקשר: עתיד ה-transports של MCP","speaker_he":"שון סמית׳ · Hugging Face","summary":"שון סמית׳ מציג ניסיון תפעולי משרת MCP בהאגינג פייס ואת העלות של תקשורת וניהול מצב. הוא דן בשינויים מוצעים לפרוטוקול ובדרך למדוד כמה מהתעבורה באמת מובילה לפעולה שימושית.","takeaways":["מדדים: initializations מול tool calls ו-session conversion; 10 מיליון הודעות, 1.2 מיליון initialize, 62 אלף tool calls.","שינויים: הסרת בקשות שרת-ללקוח ו-handshake האתחול, נקודת discover, cache control, elicitation דרך מספר סבבים, סטנדרטיזציה של כותרות HTTP והעתקת פרמטרים לכותרות.","בשאלות: CLI מול MCP."],"category":"כלים ופרוטוקולים","coverage":"כל התמליל הזמין נסקר. השאלות ותשובות נחתכו באמצע תשובה ('absolutely the r...'). שינויים בפרוטוקול מתוארים כפי שהוצגו בכנס, לא כמצב המפרט העדכני.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"שון סמית׳ מציג ניסיון תפעולי משרת MCP בהאגינג פייס ואת העלות של תקשורת וניהול מצב. הוא דן בשינויים מוצעים לפרוטוקול ובדרך למדוד כמה מהתעבורה באמת מובילה לפעולה שימושית.","chapters":[{"title":"פתיחה: Hugging Face ושרת ה-MCP שלה","body":"שון סמית' מ-Hugging Face (אחראי על קישוריות קוד-פתוח, MCP ויוזמות סוכנים; מתחזק של ריפוזיטורי הסקילס וכלי ה-upskill וה-fast-agent) פותח: Hugging Face הוא מרכז מרכזי למחקר למידת-מכונה  -  דאטהסטים, מודלים, פרסום מחקר. שרת ה-MCP שלהם בפרודקשן כבר יותר משנה: רכזת רב-תכליתית לסוכנים  -  חיפוש מודלים, בדיקת דאטהסטים, מחקר. הוא קונפיגורבילי: בוחרים אילו כלים פעילים דרך ה-URL או ממשק; מאפשר גישה מאומתת וגם אנונימית; ומשמש גם שער-הסקה  -  דרכו מתחברים למודלים אחרים ומייצרים תמונות ווידאו. הכול open source.","points":["שרת MCP של Hugging Face בפרודקשן יותר משנה: רכזת לסוכנים","קונפיגורבילי דרך URL, מאומת/אנונימי, וגם שער-הסקה"],"kind":"idea"},{"title":"היסטוריית התחבורות: מ-local ל-remote","body":"MCP נוצר כדו-כיווני: לקוח ושרת בזוג כמעט peer-to-peer, כמו LSP ב-IDEs. בהשקה היו שתי תחבורות: local (stdio, אותו תהליך) ו-remote (SSE)  -  בלי אימות בכלל. SSE היה קשה לפריסה, אז הושק streamable HTTP, ואימות נוסף  -  תחילה השרת כשרת-הרשאות (מורכב מדי), ואחר כך עיצוב טוב יותר של resource server. ב-Hugging Face יצאו לדרך עם החידושים. הנתונים שלהם: הגרף מראה שהמעבר מ-local ל-remote כמעט הושלם  -  הכחול (חיבורים דרך מתאם stdio-ל-remote) ירד לאפס; Claude Code התחיל רק עם stdio והיום רובו remote.","points":["MCP: דו-כיווני כמו LSP; stdio מקומי + SSE/HTTP מרוחק","אימות: משרת-הרשאות מורכב ל-resource server","המעבר מ-local ל-remote כמעט הושלם (לנתוני Hugging Face)"],"kind":"idea"},{"title":"אנליטיקה: מה בעצם למדוד בשרת MCP","body":"שאלה מעשית למפעילי שרת: מה מודדים? initializations נשמע טוב אבל מטעה: חלק מהלקוחות מאתחלים כל פתיחת כלי (התקנה ambient), אחרים מקאשים ומאתחלים רק בקריאה, ויש לקוחות לא יציבים שנכנסים ללולאות אתחול. tool calls גם מטעה: הרבה קריאות חוזרות יכול להיות סימן שעיצוב הכלים מבלבל את הסוכן. סמית' מעדיף session conversion: כמה לקוחות שמתחברים עושים לפחות קריאת-כלי אחת. וגם זה מורכב: OpenMCP ממיר 96.2% כי הוא agent builder; MCP remote fallback test אף פעם לא קורא כי הוא בדיקת fallback; ויעילות-יתר יכולה להיות cache שגוי של רשימת הכלים. בימים האחרונים Codex נראה לקוח יעיל במיוחד. הם מפרסמים דאטהסט עם כל הלקוחות והיכולות שלהם.","points":["initializations ו-tool calls מטעים; session conversion מועדף","יעילות-יתר יכולה להיות cache שגוי; הקשר הלקוח קובע"],"kind":"idea"},{"title":"האתגר הפרוטוקולי: statefulness יקר","body":"הבעיה נובעת מהעיצוב המקורי: הפרוטוקול מניח זוגיות stateful בין לקוח לשרת. הלקוח שולח initialize, השרת עונה, הלקוח שולח notification  -  כבר שתי הודעות לפני session; אז list tools/prompts/resources  -  ארבע קריאות לפני שירות ראשון; ורק אז tool call. המספרים שלהם (מדגם מיום ראשון): מתוך 10 מיליון הודעות פרוטוקול, 1.2 מיליון initialize אבל רק 62 אלף tool calls. מצב בשני הצדדים קשה לניהול, הפרוטוקול verbose, ומצב stateless חצי-מתועד גורם לאובדן אנליטיקה. בנוסף: elicitation ו-sampling דורשים ערוץ פתוח; tool-list-change notifications קשות מאוד בשרת ציבורי; session ID לא מוגדר מספיק; sticky sessions ו-load balancers שצריכים לפקוח תעבורה מסבכים שדרוגים וסקיילינג; וחיבורי SSE מתנתקים.","points":["10M הודעות: 1.2M initialize, רק 62K tool calls  -  תקורת state עצומה","sticky sessions + load balancers + SSE ניתוקים = פריסה קשה"],"kind":"idea"},{"title":"השינויים ב-spec: פישוט והסרת יכולות","body":"בעשרה החודשים האחרונים עבדו עם קבוצת העבודה על תחבורות (Google, Microsoft ואחרים) על שינויים גדולים ב-release candidate. בפעם הראשונה משתנות גם הודעות ה-JSON-RPC של stdio וגם התחבורה המרוחקת. פישוט ראשון: מסירים את היכולת של שרת לדבר עם לקוח בלי שהלקוח פנה קודם. צוות Anthropic סרק את כל שרתי ה-open source (100 מיליון טוקנים של חיפוש)  -  והמשתמש היחיד ביכולת הזו הוא סמית' עצמו, בהדגמת ה-MCP webcam שלו על הבמה (שרת שמנתח את המצלמה דרך sampling). מסירים גם את handshake האתחול: במקומו discover endpoint ליכולות, ו-endpoint נפרד לרשומים ל-list-change notifications.","points":["מסירים server-initiated requests  -  המשתמש היחיד שנמצא: סמית' עצמו (webcam demo)","בלי handshake אתחול; discover endpoint במקום"],"kind":"idea"},{"title":"Cache control ותכנון מחדש של elicitation","body":"הוספה אהובה עליו: cache control  -  השרת יכול לומר שרשימת הכלים לא תשתנה שעה או יומיים, ואפילו שבטוח לשתף אותה בין צבא של לקוחות. אפשר לגלות מידע על שרת גם מחוץ לחיבור, דרך MCP server card (מניפסט). Elicitation מעוצב מחדש: במקום שהשרת ישמור מצב וישלוח הודעות קטנות, הוא מחזיר \"צריך קלט\", הלקוח מטפל בממשק המשתמש, ושולח את הבקשה המקורית + התשובה בחזרה  -  בדיוק כמו API מודרני. בלי state שמור בצד השרת.","points":["Cache control: שיתוף רשימת כלים בין לקוחות, server card כמניפסט","Elicitation חדש: בלי state בשרת  -  כמו API רגיל"],"kind":"idea"},{"title":"HTTP standardization: ניתוב ברמת הרשת","body":"השינוי המלהיב ביותר לדבריו: standardization של HTTP. MCP משתמש ב-JSON-RPC  -  ותשתית רשת שצריכה לפקוח כל חבילת JSON זו פעולה יקרה. ב-spec החדש, מידע מסוים מובטח ב-headers, ואפשר אפילו להצהיר בתיאור הכלי שפרמטר מסוים יועתק ל-headers. דוגמה: בקשת יצירת תמונה ניתנת לניתוב בזמן הרשת לשרת המתאים. זה פותח אפשרויות פריסה חדשות לגמרי  -  MCP gateways ו-proxies נהיים הרבה יותר יעילים.","points":["מידע MCP ב-headers: ניתוב בלי פתיחת JSON-RPC","פרמטרים ל-headers: ניתוב לפי כלי/פרמטר ברמת הרשת"],"kind":"idea"},{"title":"מה זה פותח: URL אחד לכלים מורשים","body":"אחרי כל השינויים: בלי handshake ארוך, ביצועים הרבה יותר גבוהים ברמת הפרוטוקול. מה זווית הסוכן: היכולת להתחבר לסט כלים מורשה דרך URL אחד היא עצומה  -  תיאור הכלים והמטא-דאטה זמינים out-of-band, ופתאום חיבור לנקודות קצה מורשות לעבודות סוכן שרירותיות (dispatching jobs, inference) הופך משכנע. נתיב המעבר פשוט: ה-release candidate שוחרר, beta SDKs צפויים סוף החודש, ותאריך שחרור הפרוטוקול המתוכנן: 28 ביולי (לדבריו). בונוס: הם בונים תשתית סוכנים נכונה  -  כלי Monte (סנדבוקס לקוד Python שנוצר על ידי סוכנים) ומממנים bounty לשוברי סנדבוקסי Rust.","points":["URL אחד → סט כלים מורשה: dispatching ו-inference נהיים פשוטים","ציר זמן: RC שוחרר, beta SDKs סוף החודש, שחרור 28 ביולי (לדבריו)"],"kind":"idea"},{"title":"שאלות: תשתית אמיתית מול עיטוף API, ו-CLI מול MCP","body":"שאלה ראשונה: מה מבדיל חברות שבונות תשתית סוכנית אמיתית מאלו שרק עוטפות LLM APIs? תשובתו: בדיקות. התעשייה מהירה מדי להכריז שדבר טוב או רע; לפעמים עיטוף ישיר של API הוא בדיוק הנכון  -  השאלה אם בדקת והערכת את ההבדלים. שאלה שנייה: איך בוחרים בין CLI ל-MCP (למשל Playwright)? התשובה: השניים מתכנסים; MCP מצוין למשאבים מרוחקים (למשל dispatching של job אימון במקום להוריד דאטה), מועדף בארגונים כי אפשר לשלוט מה פרוס איפה, וה-MCP apps extension נותן חוויות אינטראקטיביות עשירות כמו ב-ChatGPT. ב-Hugging Face מציעים גם CLI וגם MCP.","points":["תשתית אמיתית מול עיטוף: ההבדל הוא בדיקות והערכה","CLI מול MCP: מתכנסים; MCP למרוחק ולארגונים, CLI למקומי"],"kind":"idea"},{"title":"מה מבדיל חברות שבונות תשתית סוכנית אמיתית מאלו שעוטפות LLM APIs?","body":"בדיקות. לפעמים עיטוף ישיר של API הוא הנכון  -  השאלה אם בדקת והערכת את ההבדלים.","kind":"qa"},{"title":"איך בוחרים בין CLI ל-MCP server (למשל Playwright)?","body":"השניים מתכנסים; MCP מצוין למשאבים מרוחקים ומועדף בארגונים; ב-Hugging Face מציעים את שניהם.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["הפרוטוקול המקורי של MCP היה stateful ויקר: 1.2M initialize לעומת 62K tool calls מתוך 10M הודעות (למדגם שלהם).","ה-spec החדש מפשט: בלי server-initiated requests, בלי handshake, עם discover endpoint, cache control ו-server card.","HTTP standardization שם מידע MCP ב-headers  -  ניתוב ברמת הרשת בלי פתיחת JSON-RPC, ופתיחת פריסות gateway חדשות.","התוצאה: URL אחד לסט כלים מורשה  -  תשתית סוכנים פרודקטיבית יותר; שחרור מתוכנן 28 ביולי (לדבריו)."],"kind":"idea"}],"diagram":{"title":"המסע של MCP ב-Hugging Face: מ-stateful יקר ל-stateless מנותב","structure":"התחלה: פרוטוקול דו-כיווני עם זוגיות stateful → תקורת initialize עצומה ופריסה קשה → שינויי ה-spec: הסרת server-initiated, בלי handshake, discover + cache control + server card, elicitation חדש, headers לניתוב → תוצאה: URL אחד לסט כלים מורשה עם ביצועים גבוהים.","nodes":[{"id":"before","label":"לפני: זוגיות stateful, handshake, 1.2M initialize ל-62K calls"},{"id":"pain","label":"כאב: sticky sessions, SSE ניתוקים, קאש מטעה"},{"id":"changes","label":"שינויי spec: discover, cache control, elicitation חדש, headers"},{"id":"after","label":"אחרי: URL אחד → כלים מורשים, ניתוב רשת, ביצועים גבוהים"}],"edges":[{"from":"before","to":"pain","label":"תקורת state"},{"from":"pain","to":"changes","label":"קבוצת העבודה על תחבורות"},{"from":"changes","to":"after","label":"פישוט + standardization"}]},"terms":[{"term":"MCP (Model Context Protocol)","definition":"פרוטוקול דו-כיווני לחיבור סוכנים לכלים ולמשאבים: לקוחות MCP מתחברים לשרתי MCP ומשנים יחד את הקונטקסט."},{"term":"SSE / Streamable HTTP","definition":"תחבורות remote של MCP: SSE הייתה הראשונה וקשה לפריסה; streamable HTTP נועד לפשט את הפריסה."},{"term":"Session conversion","definition":"אחוז הלקוחות שמתחברים ומבצעים לפחות קריאת-כלי אחת  -  המדד המועדף על סמית' להבנת פעילות."},{"term":"Stateful pairing","definition":"הנחת הפרוטוקול המקורית שהלקוח והשרת מחזיקים מצב משותף לאורך session  -  מקור המורכבות התפעולית."},{"term":"Sampling / Elicitation","definition":"יכולות של שרת לבקש מהלקוח (למשל הנחיית משתמש או פלט מודל); דורשות ערוץ פתוח ומוסרות/מעוצבות מחדש ב-spec החדש."},{"term":"MCP server card","definition":"מניפסט המתאר את השרת (יכולות, כלים)  -  מאפשר גילוי מידע מחוץ לחיבור פעיל."}],"gaps":["ההדגמה החיה (MCP webcam) הצליחה אך תיאור המצלמה לא הושמע במלואו בתמליל. תאריכי ה-beta והשחרור (28 ביולי) מובאים כדברי הדובר. המדדים (10M הודעות, 1.2M initialize, 62K calls, 96.2% conversion) הם מדגמים של הדובר, לא עובדות מאומתות."],"source_refs":["https://www.youtube.com/watch?v=nfwNjmZSKMY"]},{"number":13,"id":"78KQVxMTAQ4","url":"https://www.youtube.com/watch?v=78KQVxMTAQ4","type":"session","type_he":"סשן","duration":"30:18 דקות","title_he":"מיומנויות בכל מקום: הקשר ארגוני ב-Cisco","speaker_he":"ג׳ון גרוצינגר · Cisco","summary":"ג'ון מציג שני סיפורים מ-Cisco: המרת מאמרי ידע של צוות התמיכה למיומנויות עם בדיקות הערכה, ושימוש בסקיל כדי להפיץ מסגרת בדיקות הערכה לשמונה צוותי פיתוח.","takeaways":["רק מאמרי KB שמתוחזקים הופכים למיומנויות; הסוכן בונה, ואדם מאמת את ה-eval.","שינוי קטן שעובר eval משוחרר אוטומטית, שינוי גדול דורש אדם, נושא חדש דורש eval חדש.","Evals כבדיקות יחידה לסוכנים: סכמת dataset אחידה, הרצה מול endpoint, בדיקת כלים, טוקנים והשהיה מול baseline.","סקיל שמלמד סוכן קידוד לבנות בדיקות הערכה אחידים בכל הצוותים; README ו-SKILL דומים כ-80%.","סנכרון דטרמיניסטי של README ל-Confluence נגד סטייה.","התחלה קטנה, גרסאות סמנטיות; ההקשר הוא ההשקעה העמידה."],"category":"הקשר וזיכרון","coverage":"כל התמליל הזמין נסקר. השאלות ותשובות נחתכו באמצע תשובה ('each e').","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"ג'ון מציג שני סיפורים מ-Cisco: המרת מאמרי ידע של צוות התמיכה למיומנויות עם בדיקות הערכה, ושימוש בסקיל כדי להפיץ מסגרת בדיקות הערכה לשמונה צוותי פיתוח.","chapters":[{"title":"פתיחה: לא צריך מודל חכם יותר  -  צריך קונטקסט חכם יותר","body":"ג'ון גרוצינגר, מהנדס ראשי ב-Cisco (14 שנה; הגיע ברכישת Sourcefire, 12 שנה ב-TAC  -  התמיכה הטכנית ללקוחות ארגוניים), פותח באמירה מכוונת-פרובוקציה: לא צריך מודל חכם יותר היום  -  המודלים כבר מסוגלים לערך עסקי. הבעיה היא קונטקסט חכם יותר והנדסת קונטקסט חכמה יותר. במשך שנים הוא קפץ מ-harness ל-harness, שבר workflows, והאשים את המודל. אז הגיעו הסקילס ושינו פרספקטיבה: היום הוא עובד בעיקר עם מודלים בינוניים, ורק לעיתים נדירות עם הגבוהים.","points":["לא צריך מודל חכם יותר  -  צריך קונטקסט חכם יותר","המעבר ממודלים גבוהים לבינוניים עם סקילס טובים"],"kind":"idea"},{"title":"הבעיה האמיתית: עלויות של fan-out והערכות","body":"דפוסי fan-out סוכניים (המודל פורס 15 תת-סוכנים) מייקרים מאוד  -  בארגון הגדול שלהם התחילו להגביל שימוש במודלים בגלל העלות. הוא שאל: למה לא sonnet לכל דבר? וגילה שאפשר. המפתח: evals. צריך להשקיע מאמץ הנדסי בבניית הערכות לקונטקסט  -  ואז אפשר להשתמש במודלים נמוכים וזולים בתהליכים חוזרניים ולקבל תוצאות דטרמיניסטיות. אף אחד לא יבחר במודל היקר והאיטי אם הזול נותן אותה תוצאה.","points":["fan-out של סוכנים יקר  -  העלות כבר בעיה ארגונית","evals טובות = מודלים זולים עם תוצאות דטרמיניסטיות"],"kind":"idea"},{"title":"מה זה סקיל: מקובץ markdown לצינור","body":"סקיל יכול להיות פשוט או מורכב: המינימום הוא קובץ SKILL.md כנקודת פתיחה לסוכן. דוגמה: סקיל \"תקני ריפוזיטורי\"  -  כי מודלים מוציאים requirements.txt עם pip בעוד הוא דורש UV; הסקיל מונע הקמת פרויקטים לא נכונה. סקיל יכול לכלול חוקים (markdown נוסף), סקריפטים ו-scaffolding. החשוב: להוסיף eval לסקיל  -  להגדיר את המינימום שהוא תמיד יעשה טוב, ולעדכן evals כשמתווספים מקרי קצה. הוא מדגיש: אלה לא case studies מחייבים אלא דפוסים שניסו  -  צוות פיתוח תחת לחץ דדליינים (ההנהלה מצפה: \"יש לכם AI, תספקו יותר\") וצוותי תמיכה תחת לחץ תקלות.","points":["סקיל = SKILL.md + חוקים + סקריפטים; המינימום מוגדר על ידי eval","דפוסים מהשטח: צוות פיתוח וצוותי תמיכה תחת לחץ"],"kind":"idea"},{"title":"סיפור 1: ממאגר ידע לאנשים  -  לסקילס לסוכנים","body":"ב-Cisco TAC יש תרבות חזקה של מאגר ידע: מהנדסים מתחלפים, והערך האמיתי הוא הניסיון  -  \"עזרתי ללקוח בבעיה מורכבת, אכתוב את זה כדי שהבא לא יסבול\". השאלה: איך הופכים את התוכן האנושי לשמיש לסוכנים בלי המצאה מחדש ובלי סחף? פתרון ראשון (תת-סוכנים ששואבים הכול) לא עבד  -  הזיות ותוכן מסריח. אז שני מהנדסים בנו פלטפורמה שממירה מאמרים נבחרים (לא כל מאמר  -  רק אלה שמתוחזקים באיכות גבוהה) לסקילס, עם evals. כשמאמר משתנה, צינור (כמו GitHub Action) שולח את השינוי ל-LLM שמסווג מינורי/משני/מרכזי, מעדכן את הסקיל ומריץ evals: שינוי מינורי שעובר  -  משוחרר אוטומטית; שינוי מרכזי (נושא חדש)  -  דורש שער אנושי. הבני האדם בקצוות: מאמתים איכות וטעם  -  לא בדיקת text diffs (זו בזבוז זמן).","points":["מאמרי ידע נבחרים → סקילס עם evals; צינור עדכון אוטומטי","בני אדם בקצוות (איכות/טעם), לא באמצע (text diffs)"],"kind":"idea"},{"title":"אל תכתבו סקיל ביד  -  הסקיל הוא לסוכן","body":"הוא שואל את הקהל: כמה כתבו סקיל? רוב הידיים. כמה כתבו ביד?  -  \"תפסיקו. הסקיל הוא לא בשבילכם, הוא בשביל הסוכן.\" לא אמור לעניין אתכם מה בתוך הסקיל  -  אלא התוצאה שהסוכן מוציא איתו. זמן האדם (המשאב היקר) צריך ללכת לאימות הטעם והאיכות  -  כלומר ה-eval. ואת הכתיבה עצמה? תנו ל-LLM. אפילו טוב יותר: תנו למודל קטן לבנות לעצמו את הסקיל  -  \"הנה, זה בשבילך, איך אתה רוצה לארגן את המידע?\"  -  עם eval שמאמת איכות. אנשים אומרים \"ויקי זה מקום שדוקס מתים בו\"  -  ב-Cisco ההפך: הדוקס חשובים יותר כי הם מקרקעים את הסוכנים. הבעיה היא סוכנים שבונים זיכרונות משלהם שסוטים מהתוכן  -  ואז תשובה ללקוח לא מיושרת עם המאמר שהיא מצטטת, וכולם מאבדים אמון במערכת.","points":["הסקיל לסוכן, לא לך: בנה אותו עם LLM, אמת עם evals","סכנת הסחף: זיכרונות סוכן שסוטים מהמאמרים = אובדן אמון"],"kind":"idea"},{"title":"סיפור 2: פלטפורמה מרובת-סוכנים ותרבות skill-first","body":"הסיפור השני מהצוות שבנה את הפלטפורמה החדשה (GA לפני שבועות, מעל 1000 משתמשים, לדבריו): מערכת תזמור מרובת-סוכנים עם \"נתב סמנטי\" (כי הם Cisco  -  לא \"מתזמר\") שמנתב ל-8 סוכנים מומחים (ועוד 10 בדרך), בבעלות צוותים שונים. הלקוח רואה ממשק אחד מאוחד עם כפתורי AI וצ'אט חופשי. האתגר: איך מעריכים מערכת כזו? הוא קיבל את תפקיד ה-go/no-go. השיטה: איתותים באים מה-traces  -  משחררים מוקדם, מנטרים, ומתאימים. בצ'אט חופשי אי אפשר לנבא מה ישאלו, אז שולפים evals מדאטה פרודקשן: שאלה שלא הלכה טוב → eval חדש. אבל תיקון באג משנה פרומפט  -  ומה עוד זה שובר? בלי evals לא תדע. Evals הן unit tests לסוכנים.","points":["פלטפורמה: נתב סמנטי + 8 סוכנים מומחים + ממשק אחד","evals = unit tests לסוכנים; שולפים evals מדאטה פרודקשן"],"kind":"idea"},{"title":"Evals כמבחני יחידה: סכמה אחידה, JSONL, endpoint","body":"המסגרת שלו: סכמת דאטהסט בסיסית אחידה לכולם, שמורה בריפו עם הקוד. מעבר מ-JSON (קובץ שורה אחת ענקית שמפוצץ קונטקסט) ל-JSONL  -  כל דוגמה שורה, סוכן הקוד עורך בדיוק. אין אצירת דאטהסטים ביד  -  אין זמן; סוכן הקוד מעדכן. הקוד עובד בכל סביבה (מקומי, dev, staging): בלי import  -  הערכה מול endpoint. מפעילים את הסוכן, ובודקים במערכת התצפית (LangSmith): האם קרא לכלים הנכונים בפרמטרים הנכונים, כמה טוקנים בערך, מה ה-latency מול baseline. כל זה ב-eval.","points":["JSONL במקום JSON: סוכן עורך שורות בדיוק","eval מול endpoint + observability: כלים, פרמטרים, טוקנים, latency"],"kind":"idea"},{"title":"להפיץ ל-8 צוותים עולמיים: לא פגישה  -  סקיל","body":"איך מלמדים 8 צוותים מפוזרים בעולם את מסגרת ה-evals בשבוע-שבועיים? פגישה לא תעבוד  -  אף מפתח לא מתרגש מטסטים. אז: כולם יש סוכן קוד  -  בונים סקיל. הוא בנה plugin עם SKILL.md, דוגמאות וסקריפטים  -  עבד קשה עם סוכן אחד על דפוסים טובים, ואז ביקש מהסוכן לכתוב סקיל לאחרים. שחרר בהדרגה: צוות אחד, משוב, עוד צוות  -  ובסוף השבוע לכל הצוותים היו דאטהסטים אחידים, אותן מדדים. בלי זה? כל צוות עם סקאלה משלו (0-10, 0-5...)  -  בלגן. הבעיה הבאה: מנהלים שואלים \"תראה לי את המסגרת\"  -  ואין להם סוכן קוד.","points":["סקיל במקום פגישה: סוכן הקוד בונה את ה-evals למפתח","אחידות מדדים בין 8 צוותים  -  אחרת בלגן סקאלות"],"kind":"idea"},{"title":"מקור אמת אחד: README + Confluence בלי סחף","body":"הפתרון למנהלים: הכול בריפו. SKILL.md לסוכן, README.md לאדם  -  שניהם מתוחזקים בסוכן, מאומתים על ידי אדם ו-evals. אבל מנהלים לא ב-git  -  הם ב-Jira ו-Confluence. אז סקריפט דטרמיניסטי (בלי LLM  -  יקר בטוקנים לסינכרון פשוט) ממיר את ה-markdown ל-HTML יפה ומסנכרן ל-Confluence. עכשיו מה שהסוכנים קוראים, מה שהמנהלים קוראים  -  אותו תוכן, מקור אחד, בלי סחף. והשינוי התרבותי: השאלה הראשונה היא \"האם יש לזה סקיל?\"  -  מישהו שואל איך מתחברים ל-Kubernetes? אל תענה  -  שאל אם יש סקיל. ולא 15 מהנדסים עם 15 סקילס לאותו דבר  -  משתפים ומתחזקים יחד עם evals.","points":["מקור אמת אחד: SKILL.md לסוכן + README לאדם + סינכרון דטרמיניסטי ל-Confluence","תרבות: \"יש לזה סקיל?\" כתגובת ברירת-מחדל"],"kind":"idea"},{"title":"מה לעשות ביום שני + שאלות","body":"מעשי: להתחיל קטן  -  workflow אחד, דבר שאתה מסביר שוב ושוב  -  ולהפוך לסקיל; לחשוב מי הקהלים ובאילו פלטפורמות; להוסיף evals (בלעדיהם זה יתפרק); לשתף בהדרגה ולגרס סמנטית: 0.0.x לשיתוף ראשוני, 0.x ליציבות, 1.0 כשכולם אומרים שזה עובד  -  גרסה היא אות אמון. בשאלות: README ו-SKILL דומים ב-80% (הוא מתחיל בסקיל ומבקש README); איך מונעים פיצוץ סקילס בסקייל  -  אינדוקס שמיש לחיפוש על ידי סוכן (Tessl או grep בריפו); סקילס בריפו נפרד לכל צוות; עדכונים  -  כולם יכולים PRs כמו ספרייה משותפת, וה-evals שומרים שלא שוברים.","points":["להתחיל קטן: סקיל אחד + evals + גרסאות סמנטיות כאות אמון","Q&A: אינדוקס לחיפוש סקילס; PRs כמו ספרייה משותפת עם evals"],"kind":"idea"},{"title":"האם ה-SKILL.md וה-README שונים מאוד?","body":"כ-80% דומים; מתחיל בסקיל ומבקש README  -  מרגיש מבזבז אבל ה-LLM מתחזק.","kind":"qa"},{"title":"איך מונעים פיצוץ סקילס בסקייל  -  איך משתמש מוצא את הנכון?","body":"אינדוקס שמיש לחיפוש על ידי סוכן (Tessl או grep בריפו אחד)  -  תלוי בכלים.","kind":"qa"},{"title":"סקילס בריפו נפרד או בתוך הפרויקט?","body":"ריפו נפרד לכל צוות הנדסה, עם הרשאות גישה.","kind":"qa"},{"title":"איך מעריכים מתי סקיל צריך עדכון  -  האם כולם חופשיים לעדכן?","body":"כולם יכולים PRs כמו ספרייה משותפת; ה-evals מכסים את הפונקציונליות ושומרים שלא שוברים.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["לא צריך מודל חכם יותר  -  צריך קונטקסט חכם יותר עם evals; אז אפשר מודלים זולים ודטרמיניסטיים.","הסקיל הוא לסוכן, לא לך: בנה אותו עם LLM (אפילו קטן), אמת איכות עם evals  -  האדם מאמת טעם, לא text diffs.","מקור אמת אחד בריפו: SKILL.md לסוכן + README לאדם + סינכרון דטרמיניסטי ל-Confluence  -  בלי סחף.","Evals הן מבחני היחידה של הסוכנים; תרבות skill-first: \"יש לזה סקיל?\" כשאלת ברירת-מחדל."],"kind":"idea"}],"diagram":{"title":"המודל של גרוצינגר: קונטקסט כהשקעה עמידה עם evals","structure":"מקור אמת אחד (ריפו) מזין שני ערוצים: SKILL.md לסוכן ו-README לאדם (עם סינכרון דטרמיניסטי ל-Confluence). צינור עדכונים: שינוי מאמר → LLM מסווג → עדכון סקיל → evals → שחרור אוטומטי (מינורי) או שער אנושי (מרכזי). Evals מאפשרות מודלים זולים ודטרמיניזם.","nodes":[{"id":"source","label":"מקור אמת אחד: ריפו git עם SKILL.md + README.md"},{"id":"pipeline","label":"צינור: שינוי → סיווג LLM → עדכון → evals"},{"id":"gates","label":"שערים: מינורי=אוטומטי, מרכזי=אדם"},{"id":"channels","label":"ערוצים: סוכן (skill), אדם (README), Confluence (סינכרון)"},{"id":"evals","label":"Evals: מבחני יחידה לסוכן  -  מאפשרים מודלים זולים"}],"edges":[{"from":"source","to":"pipeline","label":"שינוי מפעיל צינור"},{"from":"pipeline","to":"gates","label":"סיווג מינורי/מרכזי"},{"from":"gates","to":"channels","label":"שחרור מבוקר"},{"from":"evals","to":"gates","label":"אימות לפני שחרור"}]},"terms":[{"term":"הנדסת קונטקסט (Context engineering)","definition":"אריזה, תחזוקה וחלוקה של הקונטקסט שהסוכן צריך  -  במקום לצפות שהמודל ינחש."},{"term":"Evals (הערכות)","definition":"מבחנים מוגדרים לקונטקסט/סקיל: מגדירים את המינימום שהסקיל חייב לעשות טוב, ובודקים שלא נשבר בעדכונים."},{"term":"Skill (סקיל)","definition":"חבילת קונטקסט לסוכן: קובץ SKILL.md ועוד חוקים/סקריפטים/scaffolding  -  נקודת הפתיחה של הסוכן."},{"term":"נתב סמנטי (Semantic router)","definition":"רכיב שמנתב בקשות משתמש לסוכן המומחה המתאים בפלטפורמה מרובת-סוכנים."},{"term":"JSONL","definition":"פורמט שבו כל דוגמת eval היא שורה נפרדת  -  מאפשר עריכה מדויקת על ידי סוכני קוד (בניגוד ל-JSON חד-שורתי ענק)."}],"gaps":["מספרים (מעל 1000 משתמשים בשבועות, 8 סוכנים + 10 בדרך, 80% דמיון README/SKILL) מובאים כדברי הדובר. שאלת הקהל האחרונה (עוד מקורות על evals) נענתה בהצעה לדבר אחרי ההרצאה  -  אין תוכן נוסף במקור."],"source_refs":["https://www.youtube.com/watch?v=78KQVxMTAQ4"]},{"number":14,"id":"tf6VNGH3tRk","url":"https://www.youtube.com/watch?v=tf6VNGH3tRk","type":"session","type_he":"סשן","duration":"28:15 דקות","title_he":"הנדסת מעטפת הסוכן מעבר לקוד: אילוצי מוצר ועיצוב לסוכנים","speaker_he":"מארק סלואן · Tessl","summary":"מארק מראה בדוגמת כפתור Export שסוכן יכול לעבור PR ו-בדיקות הערכה ועדיין לפספס הקשר מוצר ועיצוב שחי מחוץ לקוד (Figma, Linear, Notion, CRM), ומפרט ארבע בעיות ושלושה כיוונים.","takeaways":["הסוכן בחר כפתור גנרי במקום רכיב Export של מערכת העיצוב והחמיץ נגישות.","ההקשר חי מחוץ לקוד ומתיישן בשני הכיוונים.","MCP מוסיף חיבור חי, מגבלות קצב ובעיות בדיקות הערכה.","לקחים מ-Figma Code Connect.","כיוונים: כלים נפתחים, סוכן מתווך, או בליעה במאגר; כל תפקיד אולי יקבל מעטפת הסוכן משלו.","בשאלה על גבול הקשר: אותם עקרונות כמו הקשר קוד."],"category":"מוצר וארגון","coverage":"כל התמליל הזמין נסקר. אין פערים בתמלול.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"מארק מראה בדוגמת כפתור Export שסוכן יכול לעבור PR ו-בדיקות הערכה ועדיין לפספס הקשר מוצר ועיצוב שחי מחוץ לקוד (Figma, Linear, Notion, CRM), ומפרט ארבע בעיות ושלושה כיוונים.","chapters":[{"title":"פתיחה: הרצאה על לא-מפתחים בכנס מפתחים","body":"מארק סלואן מצוות המוצר של Tessl פותח: הוא כאן בכנס מפתחים כדי לדבר על לא-מפתחים  -  מנהלי מוצר, מעצבים, מנהלים. ההרצאה על העבודה שהם יוצרים, אבל היא לכולם: הרבה מהקונטקסט שאנחנו נותנים לסוכני קוד מקורו בצוותי מוצר ועיצוב. ב-24 השעות של הכנס השיחה הייתה על דבר אחד: לתת לסוכנים את הקונטקסט הנכון. המתודולוגיה התפתחה מ-spec-driven development להנדסת קונטקסט, וממנה להנדסת harness  -  אבל רובה התמקדה בקונטקסט שחי בתוך הקודבסיס.","points":["הרבה מהקונטקסט לסוכנים מקורו בלא-מפתחים: מוצר ועיצוב","מהתפתחות: spec-driven → הנדסת קונטקסט → הנדסת harness"],"kind":"idea"},{"title":"הדוגמה: כפתור ה-export שהסוכן פספס","body":"תרחיש טיפוסי: לקוח מבקש כפתור export בדשבורד (הפיצ'ר היה חבוי בתפריט הגדרות). נשמע מושלם לסוכן: טיקט Linear, עיצוב Figma, יוצא PR, הלקוח מרוצה. אבל הסוכן טעה: השתמש בקומפוננטת כפתור React גנרית ולא בקומפוננטת ה-export הייעודית. בקומפוננטה הייעודית מקודדים דרישות נגישות ודפוסי אינטראקציה לפעולה אסינכרונית  -  וכל זה הוחמץ. המטריד: מבחינת ה-harness הכול עבד חלק  -  הטיקט בוצע, ה-PR עבר, ה-evals עברו. ההשלכות יכולות להיות אמיתיות: כשל בביקורת נגישות שמעכבת עסקה קריטית.","points":["הסוכן עשה \"הכול נכון\" לפי ה-harness  -  אבל פספס את קומפוננטת ה-export עם דרישות הנגישות","ה-evals עברו; הבעיה הייתה קונטקסט מוצר/עיצוב חסר"],"kind":"idea"},{"title":"אתגר 1: הקונטקסט חי מחוץ לקודבסיס  -  בכוונה","body":"הקונטקסט היה שם כל הזמן  -  במערכת העיצוב ב-Figma; אפילו העיצוב בטיקט השתמש בקומפוננטה הנכונה, אבל הסוכן התייחס ל-Figma כטיפול ויזואלי והסיק כפתור גנרי. האתגר הראשון: קונטקסט מוצר ועיצוב חי מחוץ לקודבסיס  -  בכוונה. מעצבים ימשיכו לעבוד ב-Figma כי שם הקנבס; PMs ב-Linear ו-Notion; דאטה לקוחות ב-CRM. הקודבסיס עיוור לזה  -  ולכן גם הסוכן וה-harness. ולא רק הקונטקסט לביצוע העבודה: גם הקונטקסט להבין אם העבודה בוצעה נכון.","points":["מוצר/עיצוב חיים בכלים חיצוניים (Figma, Linear, CRM)  -  בכוונה","הקודבסיס עיוור; גם הקונטקסט לאימות נכונות חי בחוץ"],"kind":"idea"},{"title":"אתגר 2: שני העולמות יוצאים מסנכרון","body":"הצוות פתר: Storybook עם כל קומפוננטות העיצוב מתועדות  -  והפעם הבאה הסוכן בחר נכון. אבל העולם ממשיך להתפתח: עסקה חדשה עם סוכנות ממשלתית מביאה דרישות נגישות חדשות; ה-PM מעדכן Notion, המעצבים מעדכנים Figma  -  והקודבסיס נשאר מאחור, והסוכן בונה עם מערכת עיצוב מיושנת. וזה דו-כיווני: ככל שיותר סוכנים בונים קומפוננטות בקוד, האפליקציה מלאה בקומפוננטות שצוות העיצוב לא מכיר  -  צריך להזיז קונטקסט גם אחורה.","points":["Storybook פתר  -  אבל הקונטקסט משתנה; הקוד נשאר מאחור","דו-כיווני: סוכנים בונים קומפוננטות שהמעצבים לא מכירים"],"kind":"idea"},{"title":"אתגר 3: חיבור חי דרך MCP  -  לא פתרון מלא","body":"אולי זה פתור עם MCP servers? חלקית  -  אבל חיבור חי מציב אתגרים חדשים: rate limits, עלויות, זמינות צד-שלישי. וה-evals שהקמנו על הסקילס בקודבסיס הופכים תלויים בקונטקסט חיצוני שמשתנה כל הזמן ובלי מקור אמת קנוני אחד. וזו טבעו של קונטקסט מוצר/עיצוב: הוא תמיד בעדכון, אין \"definition of done\", הוא יכול להיות במצב לא-שלם מטבעו. אם בונים harness שתלוי בזה  -  צריך זהירות.","points":["MCP עוזר אבל: rate limits, עלויות, זמינות, אין מקור אמת קנוני","קונטקסט מוצר/עיצוב תמיד חלקי ובשינוי  -  evals תלויים בו זה מסוכן"],"kind":"idea"},{"title":"הלקחים מ-Figma: Code Connect והתחזוקה הייעודית","body":"זה לא תיאורטי: לפני Tessl סלואן עבד ב-Figma על Dev Mode  -  המסירה של עיצובים למפתחים (אנושיים, אז). זה התפתח לשרת ה-MCP של Figma  -  אותו קונטקסט עיצוב, ישירות לסוכן. ובבנייתו ראו את הבעיות: סוכנים ייצרו קוד שנראה מושלם אבל המציאו קומפוננטות במקום להשתמש בקיימות, או פספסו את מערכת העיצוב. הפתרון המוקדם: Code Connect  -  חיבור מפורש בין קומפוננטות עיצוב לשקילות שלהן בקוד. הלקחים: (1) החיבור דורש תחזוקה ייעודית  -  בארגונים יש צוותים שלמים שזו עבודתם; (2) לפעמים לא רוצים סנכרון מלא  -  העולמות מתפתחים בקצבים שונים, והתפקיד הוא שהסטטוס-קוו יהיה פונקציונלי; (3) אילוצים עסקיים: Figma הגנה על ה-IP של מערכת העיצוב  -  איזון בין תמיכה בסוכנים לשמירת ה-moat; נכון לכל ספקי ה-SaaS.","points":["Code Connect: חיבור מפורש קומפוננטה↔קוד דורש תחזוקה ייעודית","לפעמים לא רוצים סנכרון מלא; אילוצי IP/עסקיים מעצבים את הפתרון"],"kind":"idea"},{"title":"שלושה כיוונים אפשריים ל-harness","body":"סלואן רואה שלושה כיוונים (ועוד אחד מתחבא): (1) הכלים נפתחים  -  שרתי MCP, APIs, CLIs מתרבים, אבל עם rate limits ומסלולי מונטיזציה  -  יגיע חלק מהדרך; (2) סוכן מתווך בין קונטקסט המוצר/עיצוב לסוכן ה-harness  -  הצוותים שמתחזקים את החיבור כבר משתמשים בסוכנים, וסוכן ה-harness עצמו (כמו הסוכן של Tessl) יכול להתרחב לנהל גם קונטקסט חיצוני; (3) הריפו בולע את הקונטקסט  -  משיכה אורגנית של הדאטה למקום מנוהל, מגוּרס ומאוּמּת. צריך לפגוש מעצבים ו-PMs איפה שהם (הקנבס, ה-CRM)  -  אבל הערך שבניהול בתוך ה-harness עצום. בונוס: הלא-מפתחים הופכים מפתחים  -  PMs ומעצבים פותחים PRs  -  אולי זה הדחף לקפל את הקונטקסט פנימה.","points":["כיוונים: פתיחת כלים (MCP), סוכן מתווך, הריפו בולע את הקונטקסט","הלא-מפתחים הופכים מפתחים  -  אולי זה הדחף"],"kind":"idea"},{"title":"הכיוון ההפוך: קונטקסט קוד להחלטות מוצר","body":"חזרה לדוגמה  -  הפעם בלי מפתח בכלל: ה-PM תמלל שיחת לקוח ב-Granola, הזין ל-Claude ב-Cowork עם סקילס משלו (זיהוי פיצ'רים, טיקטים ב-Linear, סקיל שמקודד את הרודמאפ)  -  והפיצ'ר נבנה. אבל ה-PM לא ידע: יש סיבה שה-export היה חבוי  -  החלטה ארכיטקטונית ישנה עשתה אותו יקר מאוד להרצה. ה-PR ענק, וה-PM מחא כף בבורות. החסר: המשוב הטכני שעוזר להבין מאמץ וחוב טכני  -  לדעת מתי לא לבנות שווה כמו הבקלוג כרשימת מטלות לסוכנים. אולי הפתרון: לכל תפקיד בצוות מוצר סוכן ו-harness משלו  -  וה-harnesses ידברו ביניהם.","points":["PM עם סוכנים בנה פיצ'ר  -  בלי לדעת שהוא יקר ארכיטקטונית","צריך גם קונטקסט קוד להחלטות מוצר; אולי harness לכל תפקיד"],"kind":"idea"},{"title":"סיכום ושאלות","body":"סיכום: לא ברור לאן זה הולך, אבל ברור שקונטקסט מוצר ועיצוב קריטי לסוכני קוד  -  וצריך לקחת אותו בחשבון ב-harnesses. בשאלה: איפה עובר הקו  -  מה מכניסים לקודבסיס (Slack? מיילים?)? תשובתו: זו הבעיה הליבה של הנדסת קונטקסט בכלל; מוצר/עיצוב רק מקשה כי הוא מבולגן יותר ובמקומות רבים. אותם כלים: להבחין אות מרעש (אולי עם סוכנים), לכווץ לפורמטים שחיים כסקילס, ו-evals שמוודאים שהסוכן נעזר ולא מוצף. ניסוי וטעייה ואמידה.","points":["קונטקסט מוצר/עיצוב קריטי  -  לקחת בחשבון ב-harness","איפה הקו? אות מרעש + כיווץ + evals  -  אותם כלים כמו קונטקסט קוד"],"kind":"idea"},{"title":"איפה עובר הקו  -  איזה קונטקסט להכניס לסוכן (Slack, מיילים, שיחות לקוח)?","body":"זו בעיית הליבה של הנדסת קונטקסט; אותם כלים: להבחין אות מרעש (אולי עם סוכנים), לכווץ לפורמטים, ו-evals שמוודאים שהסוכן נעזר ולא מוצף  -  ניסוי ואמידה.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["קונטקסט מוצר ועיצוב קריטי לסוכני קוד  -  והוא חי מחוץ לקודבסיס בכוונה (Figma, Linear, CRM).","שני העולמות יוצאים מסנכרון דו-כיוונית; גם כשה-harness \"עובד\"  -  הסוכן יכול לפספס את הקונטקסט הנכון.","חיבור חי (MCP) עוזר אבל מציב אתגרים: rate limits, עלויות, אין מקור אמת קנוני  -  evals הופכים שבירים.","שלושה כיוונים: פתיחת כלים, סוכן מתווך, הריפו בולע את הקונטקסט; וגם הכיוון ההפוך  -  קונטקסט קוד להחלטות מוצר."],"kind":"idea"}],"diagram":{"title":"המודל של סלואן: קונטקסט מוצר/עיצוב מחוץ ל-harness","structure":"שכבות: כלים חיצוניים (Figma/Linear/CRM) ← סכנת סחף → harness (סקילס+evals+hooks) ← עוטף → קודבסיס. שלושה כיווני גישור: פתיחת כלים (MCP), סוכן מתווך, הריפו בולע. וכיוון הפוך: קונטקסט קוד להחלטות מוצר.","nodes":[{"id":"external","label":"כלים חיצוניים: Figma, Linear, Notion, CRM"},{"id":"gap","label":"הפער: סחף דו-כיווני, אין מקור אמת קנוני"},{"id":"harness","label":"Harness: סקילס, evals, hooks, מדיניות"},{"id":"code","label":"הקודבסיס"},{"id":"directions","label":"כיוונים: MCP פתוח | סוכן מתווך | הריפו בולע"}],"edges":[{"from":"external","to":"gap","label":"קונטקסט חי בחוץ בכוונה"},{"from":"gap","to":"harness","label":"צריך גישור מתוחזק"},{"from":"harness","to":"code","label":"עוטף ומנהל"},{"from":"directions","to":"gap","label":"שלושה פתרונות אפשריים"}]},"terms":[{"term":"הנדסת harness (Harness engineering)","definition":"השכבה שעוטפת את הקודבסיס: סקילס, evals, hooks, מדיניות  -  כל מה שמנהל איך הסוכן עובד מול הקוד."},{"term":"קונטקסט מוצר/עיצוב (Product & design context)","definition":"הידע שנוצר בכלים חיצוניים (Figma, Linear, Notion, CRM)  -  דרישות, עיצובים, החלטות  -  שהסוכן צריך אבל לא חי בקודבסיס."},{"term":"Figma Code Connect","definition":"כלי שמחבר מפורשות בין קומפוננטות מערכת העיצוב ב-Figma לשקילות שלהן בקודבסיס."}],"gaps":["ה\"כיוון הרביעי המתחבא\" הוצג בפועל (קונטקסט קוד להחלטות מוצר) אך נשאר פתוח כשאלה. הדוגמאות מובאות כניסיון אישי מהעבודה ב-Figma וב-Tessl; אין נתונים כמותיים לציטוט."],"source_refs":["https://www.youtube.com/watch?v=tf6VNGH3tRk"]},{"number":15,"id":"rmxRlpi7xN4","url":"https://www.youtube.com/watch?v=rmxRlpi7xN4","type":"session","type_he":"סשן","duration":"31:25 דקות","title_he":"מוח אחד, בלי סינון","speaker_he":"רוברט אוברווג","summary":"רוברט מציג 'מוח אחד' לחברה קטנה: OpenClaw, מאגר GitHub, Obsidian, Telegram, סוכן מחקר, chief of staff והקלטת פגישות.","takeaways":["חיפוש בשפה טבעית על כ-1,200-1,500 קבצים; G-Brain ו-ZeroEntropy לא הכרחיים בנפח הזה.","הקלטת פגישות (Granola, Omi) ורעיון ג'ק דורסי על היררכיה.","קשיים: קונפליקטי מיזוג, שבירה בעדכונים, הרשאות ועלות.","עצה: להתחיל עם אדם אחד, מקומית ומוקשח.","שאלות ותשובות על קנה מידה, זמן הקמה (כחודש) ו-dark factory."],"category":"הקשר וזיכרון","coverage":"כל התמליל הזמין נסקר. התמלול נחתך באמצע משפט על המסיבה אחרי המחיאות.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"רוברט מציג 'מוח אחד' לחברה קטנה: OpenClaw, מאגר GitHub, Obsidian, Telegram, סוכן מחקר, chief of staff והקלטת פגישות.","chapters":[{"title":"פתיחה: סטארטאפ קטן, נפח עצום","body":"רוברט אוברווך נפתח בכנות: הם לא ארגון ענק אלא סטארטאפ קטן  -  אולי קל להם, אבל גם קל להם להתנסות. הוא עובד באופנה: מותגים גדולים (Tommy Hilfiger, Calvin Klein, G-Star לדבריו), נפח עצום של עבודה ויזואלית  -  דמויות דיגיטליות ותמונות/וידאו מבוססי AI בסקייל, עם חמישה-שישה מודולים נוספים. צוות קטן עם תפוקה ענקית חייב לעבוד AI-native כדי לשרוד. התסכול שממנו הכול התחיל: \"איפה הקובץ הזה? איפה המצגת?\"  -  רדיפה אחרי אנשים ומידע.","points":["סטארטאפ קטן + נפח עבודה עצום = חייבים AI-native","התסכול: רדיפה אחרי קבצים וידע"],"kind":"idea"},{"title":"החזון: מוח ארגוני אחד, שני סוגי ידע","body":"החזון: להיות מחובר לכל הידע של הארגון  -  גם מה שחל בישיבות ושיחות  -  ולהשליך אותו לעבודה. שני סוגי ידע לייעל: (1) ידע חברה  -  התפתחויות חדשות, מחקר, וויקים, ידע מישיבות הופך מאובטח ונגיש; (2) צנרת היצירה  -  evals מחמירים יותר, סקילס שמאותכלים. המטרה: ללמוד ברציפות ולהציף את המידע הנכון בזמן הנכון.","points":["שני סוגי ידע: ידע חברה + צנרת יצירה","ללמוד ברציפות ולהציף מידע נכון בזמן הנכון"],"kind":"idea"},{"title":"ההתקנה הפשוטה: OpenClaw + GitHub + Obsidian + Telegram","body":"מתחילים פשוט: OpenClaw (המתזמר) בסביבת סנדבוקס; GitHub כריפוזיטורי לדאטה והמחקר; Obsidian מקומית לעיון מהיר (הוא מעדיף על Notion  -  מהיר וחד, לדבריו); ו-Telegram כמשטח התקשורת 24/7  -  מדבר לטלפון ברחוב כדי למצוא או לשתף מידע. זו נקודת הפתיחה: פשוטה, ומרחיבים ממנה בהדרגה.","points":["OpenClaw + GitHub + Obsidian + Telegram  -  ההתקנה הבסיסית","Telegram כמשטח תקשורת 24/7 עם הסוכן"],"kind":"idea"},{"title":"מה מקבלים בתמורה: sparring partner בכיס","body":"התוצאה: רוב ידע החברה בטלפון. דוגמה: שכח מה רצו ליישם בצנרת ה-CI/CD  -  שאל את הסוכן בשפה טבעית, והוא ניחש נכון (\"כנראה התכוונת ל...\"), ואפילו שאל אם זה להרצאה  -  כי הוא מבין קונטקסט. השינוי הגדול: כבר לא מחפשים קבצים  -  מחפשים רעיונות וקונטקסט. game changer.","points":["רוב ידע החברה בטלפון; הסוכן מבין קונטקסט ומשלים","מחפשים רעיונות, לא קבצים"],"kind":"idea"},{"title":"סוכנים פרואקטיביים: עיתון בוקר וניתוח סקילס","body":"סוכן מחקר פרואקטיבי: cron job שעוקב אחרי חשבונות נישה ב-X על מילים כמו \"agentic engineering\"  -  העיתון הבוקרי שלו. הלקח החשוב: לא דוחפים הכול ל-vault  -  הוא מקדם רק מה שחשוב באמת, וממנו בונה וויקים לצוות הרחב (כדי לא להעמיס). דוגמה חיה: מצא סקיל של גוגל לפירוק משימות, שאל את הסוכן אם שווה  -  הסוכן, שמכיר את הסקילס והקודבסיס שלהם, ניתח ובעקבות ניסוח מחדש ענה: \"אין כלום שאין לך כבר; ה-task files שלך מפורטים יותר\". הניתוח לקח דקה.","points":["סוכן מחקר פרואקטיבי: עיתון בוקר מ-X; מקדמים ל-vault רק את החשוב","הסוכן מנתח סקיל חיצוני מול מה שיש  -  בדקה"],"kind":"idea"},{"title":"ה-vault: 1200 קבצים לא מובנים שעובדים","body":"ה-vault שלו: כמעט 1200 קבצי מחקר לא-מובנים  -  וההתקנה מתמודדת בלי תוספות. ניסו RAG ווקטורים בהתחלה, אבל בנפח הזה לא צריך. הוא מוסיף to-dos וקישורים בין קבצים  -  מעין רכזת זיכרון. ויש וולט לקוחות נפרד: הלקוחות עובדים ב-Miro, PowerPoint, Figma  -  קשה לשנות אנשים, אז פשוט מתרגמים כל מה שהם נותנים לתוך המערכת, ושואלים בשפה טבעית: \"מה היו קבצי ה-loss האחרונים מ-Calvin Klein מאיש X?\"  -  \"איפה הנכס?\" כבר לא בעיה.","points":["1200 קבצים לא-מובנים עובדים בלי RAG מורכב (בנפח הזה)","וולט לקוחות: מתרגמים כל פורמט, שואלים בשפה טבעית"],"kind":"idea"},{"title":"הפילוסופיה: הקלטת הכול  -  דורסי, דאליו, Omi, Granola","body":"השראה: ג'ק דורסי  -  AI מאתגר בפעם הראשונה את ההנחה שהיררכיה נדרשת; אם מידע מומלד, מובן ומופץ בזמן אמת, מה נשאר מהתיווך? וריי דאליו, שהקליט כל ישיבה ב-Bridgewater לפני 10-15 שנה  -  אז נראה מוזר, היום \"הכול שלא דיגיטלי פשוט לא קיים\". אז מקליטים הכול: כל שיחה, ישיבה, מחקר וקוד. כלים: Omi (מכשיר open source שמקליט שיחות קפה לשרתים שלך  -  בלי מנוי, הבעלות על הדאטה שלך), ו-Granola שמתמלל ישיבות ומעצב את התמליל סביב הפתקים שלך. מהערות ישיבה אפשר לייצר טיוטת מצגת ראשונה. ובעתיד: chief of staff שמציף שאלות מכירה נכונות באמצע שיחה.","points":["דורסי + דאליו: אם מידע זמין בזמן אמת  -  ההיררכיה מאותגרת; מקליטים הכול","Omi + Granola: הקלטה ותמלול בבעלות עצמית"],"kind":"idea"},{"title":"keeping it real: קונפליקטים, הרשאות, AI גאון וטיפש","body":"הכנות: בניית זה מבולגנת. קונפליקטים בין Obsidian ל-GitHub  -  merge conflicts לא כיפיים. שיתוף ידע זה קשה: האם באמת משתפים כל ישיבה עם כולם? מה אם נאמר משהו שלא צריך לדלוף?  -  הם בנו גבולות בין אנשים, צוותים ולקוחות, והידע זורם בין השכבות. וה-AI יכול להיות גאון וטיפש בו זמנית  -  מפספס את המובן מאליו שאמרת עשר פעמים. וסקריפטים נשברים: פעם שהכול עובד זה עובד, אבל להוסיף דברים חדשים זו כמעט עבודה במשרה מלאה.","points":["קונפליקטים, הרשאות, גבולות בין אנשים/צוותים/לקוחות","AI גאון וטיפש בו זמנית; תחזוקה = כמעט משרה מלאה"],"kind":"idea"},{"title":"הארכיטקטורה המלאה: G-Brain, ZeroEntropy, chief of staff","body":"המערכת בפועל: וולט פרטי עם מחקר, מחובר ל-GitHub; G-Brain (של גארי טאן מ-Y Combinator, לדבריו) עם וקטור גדול דרך ZeroEntropy  -  מילות מפתח וקשרי גרף בין עמודים; אבל בנפח הנוכחי הוא לא מרגיש שהוא צריך את זה  -  שימושי בעיקר בנפחים גדולים. יש chief of staff על אינסטנס נפרד (כדי שלא ידלוף בין סביבות). Telegram לתקשורת, Obsidian לעיון, ובוחן Neo4j לשכבת סינון ידע נוספת. החיפוש: memory search סמנטי + טעינת פרוסה רלוונטית של הוולט לפי סוג משימה + G-Brain לחיפוש גדול + קריאות קבצים ישירות.","points":["G-Brain + ZeroEntropy: וקטורים וגרף  -  שימושי בעיקר בנפחים גדולים","chief of staff על אינסטנס נפרד; בוחן Neo4j"],"kind":"idea"},{"title":"עצות מעשיות + שאלות","body":"העצות: להתחיל קטן  -  תנו לאדם אחד לסבול קודם; להריץ מקומי על הלפטופ עם הקשחת אבטחה ויישור למה שמותר לעשות עם הדאטה; להקים chief of staff שגוזל 20% מהמטלות המעצבנות; וסוכן מחקר  -  \"קסם: ללמוד מהעולם דרך העדשה המאורגנת שלך\". בשאלות: סקיילינג וולט לקוחות  -  עדיין לוקאלי על לפטופ אחד, אין תשובה עדיין להרשאות והפרדה; עלות הקמה  -  חודש עבודה בערך, ואחרי זה 30 דקות (או 30 שניות לסקריפט) להקמה נוספת  -  אבל עדכונים שוברים דברים; אינטראקציית הצוות  -  80% נשאר בהנהלה, 10-15 וויקים ארוזים מקודמים לצוות; על OpenClaw  -  לא עשה סריקת שוק, התחיל מוקדם ואהב שהוא פרואקטיבי; על קידוד  -  עובדים על \"dark factory\" מלא עם OpenClaw כמתזמר, סוכנים אדברסריים לסקירה ו-Codex לבלק של העבודה.","points":["להתחיל קטן, מקומי, עם הקשחה; chief of staff + סוכן מחקר","Q&A: הרשאות עדיין לא פתורות; חודש הקמה, עדכונים שוברים"],"kind":"idea"},{"title":"איך תתמודדו עם גידול וולט הלקוחות  -  G-Brain יספיק? Neo4j?","body":"עדיין לוקאלי על לפטופ אחד; אין תשובה עדיין  -  צריך הרשאות והפרדת דאטה לדליים.","kind":"qa"},{"title":"כמה זמן עלתה ההקמה והתחזוקה?","body":"בערך חודש עבודה (ותחביב); אחרי ההקמה  -  30 דקות/שניות לסקריפט, אבל עדכוני גרסה שוברים דברים.","kind":"qa"},{"title":"איך חברי הצוות מתקשרים עם המערכת?","body":"80% נשאר בהנהלה; 10-15 וויקים ארוזים מקודמים לצוות הרחב.","kind":"qa"},{"title":"למה OpenClaw כמתזמר?","body":"לא עשה סריקת שוק  -  התחיל מוקדם אחרי השחרור, אהב שהוא פרואקטיבי; G-Brain לא נדרש בנפח הנוכחי.","kind":"qa"},{"title":"האם חשבת על Hermes? ומה עם קידוד עם סוכנים?","body":"Hermes יצא אחרי OpenClaw  -  שקל אבל אין רוחב נפשי; קידוד: בונים dark factory עם OpenClaw כמתזמר, סוכנים אדברסריים ו-Codex.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["מוח ארגוני אחד: הקליטו הכול (ישיבות, שיחות, מחקר, קוד)  -  מה שלא דיגיטלי לא קיים (ברוח דורסי ודאליו).","מתחילים פשוט: OpenClaw + GitHub + Obsidian + Telegram; 1200 קבצים לא-מובנים עובדים בלי RAG מורכב בנפח הזה.","הזהב הוא בפרואקטיביות: סוכן מחקר שמציף, chief of staff שגוזל מטלות  -  ומקדמים לצוות רק וויקים ארוזים.","הכנות: הרשאות והפרדת דאטה עדיין לא פתורות; תחזוקה כמעט משרה מלאה; AI גאון וטיפש בו זמנית."],"kind":"idea"}],"diagram":{"title":"המוח הארגוני של אוברווך: שכבות וידע","structure":"קלטים (ישיבות מוקלטות, מחקר, קבצי לקוח בכל פורמט, X) → וולטים (פרטי + לקוחות, מחוברים ל-GitHub) → שכבת חיפוש (memory search + G-Brain/ZeroEntropy + קריאות ישירות) → סוכנים (מחקר, chief of staff) → משטחים (Telegram, Obsidian) → קידום לוויקים לצוות.","nodes":[{"id":"inputs","label":"קלטים: הקלטות ישיבות (Granola/Omi), מחקר, קבצי לקוח, X"},{"id":"vaults","label":"וולטים: פרטי + לקוחות (GitHub-backed, Obsidian)"},{"id":"search","label":"חיפוש: memory search, G-Brain/ZeroEntropy, קריאות ישירות"},{"id":"agents","label":"סוכנים: מחקר פרואקטיבי, chief of staff (אינסטנס נפרד)"},{"id":"surfaces","label":"משטחים: Telegram 24/7, Obsidian, וויקים מקודמים לצוות"}],"edges":[{"from":"inputs","to":"vaults","label":"הקלטת הכול; תרגום כל פורמט"},{"from":"vaults","to":"search","label":"1200+ קבצים לא-מובנים"},{"from":"search","to":"agents","label":"שליפה לפי הקשר"},{"from":"agents","to":"surfaces","label":"עיתון בוקר, תשובות, וויקים"}]},"terms":[{"term":"מוח ארגוני (One brain)","definition":"החזון של אוברווך: כל ידע החברה  -  שיחות, ישיבות, מחקר, קוד  -  נגיש לסוכן ונשאל בשפה טבעית."},{"term":"OpenClaw","definition":"המתזמר שאוברווך בחר: מריץ סוכנים, cron jobs, חיפוש ועדכונים  -  ליבת ה\"מוח\" הארגוני שלו."},{"term":"קידום לויקי (Promote to wiki)","definition":"הדפוס שלו: תוכן חשוב מהמחקר האישי מקודם לוויקי קצר וארוז לצוות הרחב  -  בלי להעמיס."},{"term":"Dark factory","definition":"צנרת קידוד אוטונומית שאוברווך בונה: OpenClaw מתזמר, סוכנים אדברסריים סוקרים, Codex עושה את הבלק של העבודה."}],"gaps":["שאלת הסקיילינג של וולט הלקוחות נותרה בלי תשובה (הדובר הודה). ה\"חודש הקמה\" וה-80/10-15 הם הערכות הדובר. שמות הכלים (G-Brain, ZeroEntropy, Omi, Granola, Hermes, OpenClaw) מובאים כפי שהוזכרו על הבמה."],"source_refs":["https://www.youtube.com/watch?v=rmxRlpi7xN4"]}]);
